INSERT INTO `modules` (`id`, `course_id`, `title`, `content`, `video_url`, `presentation_url`, `order`, `created_at`, `updated_at`) VALUES
(9, 4, 'Sanogen tafakkur: falsafiy-psixologik va pedagogik tahlil', '<p class=\"ql-align-center\"><strong>SANOGEN&nbsp;TAFAKKUR:&nbsp;FALSAFIY-PSIXOLOGIK&nbsp;VA&nbsp;PEDAGOGIK&nbsp;TAHLIL</strong></p><p class=\"ql-align-center\"><strong>Oʻquv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;maʼruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p class=\"ql-align-justify\"><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;oʻqituvchilarida&nbsp;sanogen&nbsp;tafakkurning&nbsp;falsafiy,&nbsp;psixologik&nbsp;va&nbsp;pedagogik&nbsp;mohiyatini,&nbsp;uning&nbsp;patogen&nbsp;tafakkurdan&nbsp;farqli&nbsp;jihatlarini&nbsp;hamda&nbsp;raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;kasbiy&nbsp;salomatlik&nbsp;va&nbsp;metakognitiv&nbsp;nazoratni&nbsp;taʼminlashdagi&nbsp;oʻrnini&nbsp;shakllantirish.</p><h3 class=\"ql-align-justify\"><strong>1.&nbsp;Sanogen&nbsp;va&nbsp;patogen&nbsp;tafakkur&nbsp;tushunchalarining&nbsp;falsafiy-psixologik&nbsp;mohiyati</strong></h3><p class=\"ql-align-justify\">Zamonaviy&nbsp;taʼlim&nbsp;tizimining&nbsp;intensiv&nbsp;raqamlashuvi,&nbsp;axborot&nbsp;yuklamasining&nbsp;ortishi&nbsp;va&nbsp;pedagogik&nbsp;faoliyatdagi&nbsp;yuqori&nbsp;dinamika&nbsp;oʻqituvchidan&nbsp;nafaqat&nbsp;kasbiy-metodik&nbsp;tayyorgarlikni,&nbsp;balki&nbsp;yuqori&nbsp;darajadagi&nbsp;psixologik&nbsp;chidamlilik&nbsp;hamda&nbsp;moslashuvchanlikni&nbsp;talab&nbsp;etmoqda.&nbsp;Ushbu&nbsp;kontekstda&nbsp;shaxsning&nbsp;ruhiy&nbsp;salomatligini&nbsp;saqlash&nbsp;va&nbsp;kasbiy&nbsp;faoliyat&nbsp;samaradorligini&nbsp;oshirishda&nbsp;<strong>sanogen&nbsp;tafakkur</strong>&nbsp;(lotincha&nbsp;<em>sano</em>&nbsp;—&nbsp;davolayman,&nbsp;sogʻlomlashtiraman&nbsp;va&nbsp;yunoncha&nbsp;<em>genesis</em>&nbsp;—&nbsp;kelib&nbsp;chiqish)&nbsp;markaziy&nbsp;kategoriya&nbsp;sifatida&nbsp;namoyon&nbsp;boʻladi.</p><p class=\"ql-align-justify\">Ilmiy&nbsp;muomalaga&nbsp;sanogen&nbsp;tafakkur&nbsp;tushunchasi&nbsp;psixolog&nbsp;va&nbsp;olim&nbsp;<strong>Yu.M.&nbsp;Orlov</strong>&nbsp;tomonidan&nbsp;olib&nbsp;kirilgan&nbsp;boʻlib,&nbsp;u&nbsp;shaxsning&nbsp;oʻz&nbsp;emotsional&nbsp;holatlarini,&nbsp;ichki&nbsp;kechinmalarini&nbsp;va&nbsp;fikrlash&nbsp;naqshlarini&nbsp;(<em>thinking&nbsp;patterns</em>)&nbsp;ongli&nbsp;ravishda&nbsp;boshqarish&nbsp;va&nbsp;tartibga&nbsp;solish&nbsp;qobiliyati&nbsp;sifatida&nbsp;talqin&nbsp;etiladi.</p><p class=\"ql-align-justify\">Tafakkurning&nbsp;ikki&nbsp;qarama-qarshi&nbsp;koʻrinishi&nbsp;mavjud:</p><ol><li><strong>Patogen&nbsp;tafakkur:</strong><ul><li>Shaxsiy&nbsp;emotsional&nbsp;travmalar,&nbsp;xavotir,&nbsp;aybdorlik,&nbsp;xafagarchilik,&nbsp;kasbiy&nbsp;nosozliklar&nbsp;va&nbsp;texnofobiyani&nbsp;qayta-qayta&nbsp;anglanmagan&nbsp;holda&nbsp;miyada&nbsp;aylantirish&nbsp;(<em>rumination</em>);</li><li>Qiyin&nbsp;pedagogik&nbsp;vaziyatlarda&nbsp;muammoning&nbsp;yechimini&nbsp;izlash&nbsp;oʻrniga&nbsp;oʻzini&nbsp;yoki&nbsp;atrofdagilarni&nbsp;ayblash;</li><li>Kognitiv&nbsp;xatolarga&nbsp;(haddan&nbsp;tashqari&nbsp;umumlashtirish,&nbsp;fojialashtirish,&nbsp;&quot;yoki&nbsp;hamma&nbsp;narsa,&nbsp;yoki&nbsp;hech&nbsp;narsa&quot;&nbsp;tamoyilida&nbsp;fikrlash)&nbsp;tayanish;</li><li>Oqibatda&nbsp;kasbiy&nbsp;yonib&nbsp;bitish&nbsp;(<em>burnout&nbsp;syndrome</em>),&nbsp;ruhiy&nbsp;charchoq&nbsp;va&nbsp;psixosomatik&nbsp;kasalliklarga&nbsp;olib&nbsp;keladi.</li></ul></li><li><strong>Sanogen&nbsp;tafakkur:</strong><ul><li>Salbiy&nbsp;his-tuygʻular&nbsp;va&nbsp;psixologik&nbsp;zoʻriqishlarni&nbsp;bartaraf&nbsp;etishga&nbsp;yoʻnaltirilgan&nbsp;ongli&nbsp;metakognitiv&nbsp;faoliyat;</li><li>Xatolar&nbsp;va&nbsp;muvaffaqiyatsizliklarni&nbsp;fojia&nbsp;emas,&nbsp;balki&nbsp;qimmatli&nbsp;tajriba&nbsp;hamda&nbsp;rivojlanish&nbsp;omili&nbsp;sifatida&nbsp;qabul&nbsp;qilish;</li><li>Ishonch,&nbsp;ichki&nbsp;xotirjamlik&nbsp;va&nbsp;psixologik&nbsp;doʻstona&nbsp;muhitni&nbsp;shakllantirishga&nbsp;xizmat&nbsp;qiladi.</li></ul></li></ol><h3 class=\"ql-align-justify\"><strong>2.&nbsp;Raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;biologiya&nbsp;oʻqituvchisining&nbsp;sanogen&nbsp;tafakkurini&nbsp;rivojlantirish&nbsp;zarurati</strong></h3><p class=\"ql-align-justify\">Biologiya&nbsp;fani&nbsp;oʻzining&nbsp;xarakteriga&nbsp;koʻra&nbsp;oʻta&nbsp;dinamik&nbsp;va&nbsp;murakkab&nbsp;strukturalarga&nbsp;ega&nbsp;(mikro&nbsp;va&nbsp;makro&nbsp;olam,&nbsp;hujayraviy&nbsp;jarayonlar,&nbsp;genetik&nbsp;modellashtirish).&nbsp;Raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;ushbu&nbsp;biologik&nbsp;resurslar,&nbsp;virtual&nbsp;laboratoriyalar,&nbsp;3D&nbsp;modellar&nbsp;va&nbsp;platformalar&nbsp;bilan&nbsp;ishlash&nbsp;jarayonida&nbsp;biologiya&nbsp;oʻqituvchilarida&nbsp;ikki&nbsp;turli&nbsp;reaksiya&nbsp;yuzaga&nbsp;keladi:</p><ul><li><strong>Patogen&nbsp;reaksiya:</strong>&nbsp;Texnik&nbsp;nosozliklar,&nbsp;platformalarni&nbsp;oʻzlashtirishdagi&nbsp;murakkabliklar&nbsp;yoki&nbsp;raqamli&nbsp;savodxonlikdagi&nbsp;uzilishlar&nbsp;natijasida&nbsp;oʻqituvchida&nbsp;<em>&quot;men&nbsp;zamondan&nbsp;orqada&nbsp;qolyapman&quot;</em>,&nbsp;<em>&quot;3D&nbsp;texnologiyalar&nbsp;darsimni&nbsp;buzadi&quot;</em>&nbsp;degan&nbsp;kognitiv&nbsp;toʻsiqlar&nbsp;hamda&nbsp;xavotirlar&nbsp;shakllanadi.</li><li><strong>Sanogen&nbsp;reaksiya:</strong>&nbsp;Oʻqituvchi&nbsp;raqamli&nbsp;vositalarni&nbsp;oʻz&nbsp;imkoniyatlarini&nbsp;kengaytiruvchi&nbsp;didaktik&nbsp;koʻmakchi&nbsp;sifatida&nbsp;koʻradi,&nbsp;qiyinchiliklarni&nbsp;esa&nbsp;bosqichma-bosqich&nbsp;oʻzlashtiriladigan&nbsp;kasbiy&nbsp;vazifa&nbsp;sifatida&nbsp;qabul&nbsp;qiladi.</li></ul><p class=\"ql-align-justify\">Biologiya&nbsp;oʻqituvchisida&nbsp;sanogen&nbsp;tafakkurning&nbsp;rivojlanganligi&nbsp;unga&nbsp;katta&nbsp;hajmdagi&nbsp;biologik&nbsp;axborotlar&nbsp;oqimida&nbsp;emotsional&nbsp;barqarorlikni&nbsp;saqlash&nbsp;hamda&nbsp;oʻquvchilarga&nbsp;biologik&nbsp;bilimlarni&nbsp;erkin,&nbsp;ijodiy&nbsp;va&nbsp;qiziqarli&nbsp;yetkazib&nbsp;berish&nbsp;imkonini&nbsp;yaratadi.</p><h3 class=\"ql-align-justify\"><strong>3.&nbsp;Sanogen&nbsp;tafakkur&nbsp;kompetensiyasining&nbsp;tarkibiy&nbsp;komponentlari</strong></h3><p class=\"ql-align-justify\">Sanogen&nbsp;tafakkur&nbsp;kompleks&nbsp;kognitiv-metakognitiv&nbsp;tuzilma&nbsp;boʻlib,&nbsp;quyidagi&nbsp;5&nbsp;ta&nbsp;asosiy&nbsp;subshkala&nbsp;(komponent)&nbsp;orqali&nbsp;namoyon&nbsp;boʻladi:</p><ol><li><strong>Refleksivlik:</strong>&nbsp;Oʻz&nbsp;tafakkur&nbsp;jarayonlarini&nbsp;kuzatish,&nbsp;darsdagi&nbsp;kasbiy&nbsp;xato&nbsp;va&nbsp;muvaffaqiyatlarni&nbsp;konstruktiv&nbsp;tahlil&nbsp;qilish,&nbsp;metakognitiv&nbsp;nazorat.&nbsp;(D.&nbsp;Schon&nbsp;nazariyasi).</li><li><strong>Kognitiv&nbsp;moslashuvchanlik:</strong>&nbsp;Raqamli&nbsp;taʼlim&nbsp;muhitidagi&nbsp;yangi&nbsp;va&nbsp;kutilmagan&nbsp;vaziyatlarda&nbsp;elastik&nbsp;fikrlash,&nbsp;texnofobiyaga&nbsp;chidamlilik,&nbsp;kognitiv&nbsp;qayta&nbsp;tuzilish.</li><li><strong>Emotsional&nbsp;regulyatsiya:</strong>&nbsp;Stressli&nbsp;pedagogik&nbsp;va&nbsp;raqamli&nbsp;vaziyatlarda&nbsp;his-tuygʻularni&nbsp;ongli&nbsp;boshqarish,&nbsp;burnout&nbsp;profilaktikasi.</li><li><strong>Konstruktiv&nbsp;faollik:</strong>&nbsp;Muammoni&nbsp;ijobiy&nbsp;va&nbsp;yaratuvchanlik&nbsp;energiyasi&nbsp;orqali&nbsp;hal&nbsp;qilishga&nbsp;yoʻnaltirilgan&nbsp;fikr&nbsp;yuritish&nbsp;hamda&nbsp;harakat&nbsp;qilish.</li><li><strong>Axborot&nbsp;selektivligi:</strong>&nbsp;Katta&nbsp;hajmdagi&nbsp;raqamli&nbsp;va&nbsp;biologik&nbsp;axborotlarni&nbsp;tanqidiy&nbsp;baholash,&nbsp;ularning&nbsp;ilmiy&nbsp;ishonchliligini&nbsp;saralash.</li></ol><h3 class=\"ql-align-justify\"><strong>4.&nbsp;Metakognitiv&nbsp;nazorat&nbsp;va&nbsp;sanogen&nbsp;refleksiya&nbsp;texnikasi</strong></h3><p class=\"ql-align-justify\">Sanogen&nbsp;tafakkurni&nbsp;shakllantirishning&nbsp;bosh&nbsp;mexanizmi&nbsp;<strong>sanogen&nbsp;refleksiya</strong>&nbsp;hisoblanadi.&nbsp;Sanogen&nbsp;refleksiya&nbsp;—&nbsp;bu&nbsp;oddiy&nbsp;kechinmalardan&nbsp;uzoqlashib&nbsp;(<em>decentration</em>),&nbsp;shaxsning&nbsp;oʻz&nbsp;emotsional&nbsp;reaksiyalariga&nbsp;chetdan&nbsp;xotirjam&nbsp;va&nbsp;obyektiv&nbsp;baho&nbsp;berish&nbsp;jarayonidir.</p><p class=\"ql-align-justify\">Oʻqituvchi&nbsp;dars&nbsp;jarayonida&nbsp;yoki&nbsp;raqamli&nbsp;vositalar&nbsp;bilan&nbsp;ishlashda&nbsp;salbiy&nbsp;emotsiyani&nbsp;(xavotir,&nbsp;jahloqlik)&nbsp;his&nbsp;qilganda,&nbsp;sanogen&nbsp;refleksiya&nbsp;quyidagi&nbsp;algoritm&nbsp;boʻyicha&nbsp;amalga&nbsp;oshiriladi:</p><ol><li><strong>Emotsiyani&nbsp;anglash&nbsp;va&nbsp;nomlash:</strong>&nbsp;<em>&quot;Hozir&nbsp;men&nbsp;nima&nbsp;his&nbsp;qilyapman?&nbsp;(Masalan:&nbsp;proyektor&nbsp;ishlamagani&nbsp;uchun&nbsp;asabiylashyapman)&quot;</em>.</li><li><strong>Kognitiv&nbsp;xatoni&nbsp;ajratib&nbsp;olish:</strong>&nbsp;<em>&quot;Nega&nbsp;asabiylashyapman?&nbsp;Chunki&nbsp;barcha&nbsp;narsa&nbsp;mukammal&nbsp;boʻlishi&nbsp;kerak&nbsp;degan&nbsp;notoʻgʻri&nbsp;qolipga&nbsp;tayanyapman&quot;</em>.</li><li><strong>Konstruktiv&nbsp;refreyming&nbsp;(qayta&nbsp;baholash):</strong>&nbsp;<em>&quot;Texnik&nbsp;nosozlik&nbsp;—&nbsp;bu&nbsp;fojia&nbsp;emas,&nbsp;balki&nbsp;jonli&nbsp;dars&nbsp;jarayonining&nbsp;bir&nbsp;qismi.&nbsp;Men&nbsp;hozir&nbsp;zaxira&nbsp;rejaga&nbsp;oʻtaman&quot;</em>.</li><li><strong>Harakat&nbsp;va&nbsp;tinchlanish:</strong>&nbsp;Xotirjamlikni&nbsp;tiklash&nbsp;va&nbsp;eʼtiborni&nbsp;muammoning&nbsp;yechimiga&nbsp;qaratish.</li></ol><p class=\"ql-align-justify\"><strong>Maʼruza&nbsp;boʻyicha&nbsp;xulosa:</strong></p><p class=\"ql-align-justify\">Sanogen&nbsp;tafakkur&nbsp;—&nbsp;bu&nbsp;pedagogik&nbsp;faoliyatda&nbsp;uchraydigan&nbsp;psixologik-kognitiv&nbsp;toʻsiqlarni&nbsp;yengishning&nbsp;va&nbsp;raqamli&nbsp;taʼlim&nbsp;muhitiga&nbsp;moslashuvchanlikning&nbsp;kalitidir.&nbsp;Biologiya&nbsp;oʻqituvchisi&nbsp;sanogen&nbsp;tafakkurni&nbsp;oʻzlashtirgan&nbsp;sari,&nbsp;uning&nbsp;kasbiy&nbsp;motivatsiyasi&nbsp;barqarorlashadi&nbsp;va&nbsp;raqamli&nbsp;texnologiyalardan&nbsp;foydalanishdagi&nbsp;psixologik&nbsp;zoʻriqishlar&nbsp;bartaraf&nbsp;etiladi.</p>', '', '/storage/presentations/1784924083_1-Modul__Sanogen_Tafakkur.pptx', 1, '2026-07-24 14:44:50', '2026-07-24 15:14:43'),
(10, 4, 'PATOGEN TAFAKKURNING TURLARI VA O\'ZGARTIRISH TEXNIKALARI', '<h1>PATOGEN&nbsp;TAFAKKURNING&nbsp;TURLARI&nbsp;VA&nbsp;O&#39;ZGARTIRISH&nbsp;TEXNIKALARI</h1><p><strong>Oʻquv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;maʼruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;oʻqituvchilarida&nbsp;patogen&nbsp;tafakkurning&nbsp;turli&nbsp;koʻrinishlarini&nbsp;(xavotir,&nbsp;aybdorlik,&nbsp;xafagarchilik,&nbsp;fojialashtirish)&nbsp;aniqlash,&nbsp;ularning&nbsp;kognitiv&nbsp;ildizlarini&nbsp;tahlil&nbsp;qilish&nbsp;hamda&nbsp;ABC&nbsp;modeli&nbsp;va&nbsp;refreyming&nbsp;texnikalari&nbsp;orqali&nbsp;sanogen&nbsp;fikrlashga&nbsp;oʻtkazish&nbsp;koʻnikmalarini&nbsp;shakllantirish.</p><h2>1.&nbsp;Patogen&nbsp;tafakkurning&nbsp;turlari&nbsp;va&nbsp;ularning&nbsp;kognitiv&nbsp;ildizlari</h2><p>Pedagogik&nbsp;faoliyatda&nbsp;va&nbsp;raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;biologiya&nbsp;oʻqituvchilari&nbsp;duch&nbsp;keladigan&nbsp;ruhiy-psixologik&nbsp;toʻsiqlarning&nbsp;aksariyati&nbsp;<strong>patogen&nbsp;tafakkur&nbsp;patternlari&nbsp;(naqshlari)</strong>&nbsp;bilan&nbsp;bogʻliq.&nbsp;Kognitiv&nbsp;psixologiya&nbsp;(A.&nbsp;Beck,&nbsp;A.&nbsp;Ellis)&nbsp;hamda&nbsp;Yu.M.&nbsp;Orlovning&nbsp;sanogen&nbsp;tafakkur&nbsp;nazariyasiga&nbsp;koʻra,&nbsp;patogen&nbsp;tafakkur&nbsp;quyidagi&nbsp;asosiy&nbsp;turlarga&nbsp;boʻlinadi:</p><ol><li><strong>Xavotirlik&nbsp;va&nbsp;texnofobiya:</strong><ul><li>Raqamli&nbsp;taʼlim&nbsp;platformalari,&nbsp;3D&nbsp;modellar&nbsp;yoki&nbsp;virtual&nbsp;laboratoriyalardan&nbsp;foydalanishda&nbsp;<em>&quot;birdan&nbsp;texnika&nbsp;ishlamay&nbsp;qolsa-chi?&quot;</em>,&nbsp;<em>&quot;oʻquvchilar&nbsp;oldida&nbsp;uyatga&nbsp;qolsam-chi?&quot;</em>&nbsp;degan&nbsp;surunkali&nbsp;xavotir.</li><li>Kognitiv&nbsp;ildizi:&nbsp;Nomaʼlumlikdan&nbsp;qoʻrqish&nbsp;va&nbsp;oʻz-oʻziga&nbsp;past&nbsp;baho&nbsp;berish.</li></ul></li><li><strong>Fojialashtirish:</strong><ul><li>Kichik&nbsp;texnik&nbsp;uzilish&nbsp;yoki&nbsp;darsdagi&nbsp;xatoni&nbsp;fojia&nbsp;darajasiga&nbsp;koʻtarish&nbsp;(<em>&quot;Barcha&nbsp;rejam&nbsp;rasvo&nbsp;boʻldi&quot;,&nbsp;&quot;Men&nbsp;umuman&nbsp;yaxshi&nbsp;oʻqituvchi&nbsp;emasman&quot;</em>).</li><li>Kognitiv&nbsp;ildizi:&nbsp;&quot;Yoki&nbsp;hamma&nbsp;narsa,&nbsp;yoki&nbsp;hech&nbsp;narsa&quot;&nbsp;tamoyilidagi&nbsp;absolutistik&nbsp;fikrlash.</li></ul></li><li><strong>Aybdorlik&nbsp;hissi:</strong><ul><li>Oʻquvchilarning&nbsp;test&nbsp;natijalari&nbsp;past&nbsp;boʻlganda&nbsp;yoki&nbsp;darsda&nbsp;mavzuni&nbsp;oʻzlashtira&nbsp;olishmaganda,&nbsp;obyektiv&nbsp;sabablarni&nbsp;tahlil&nbsp;qilmay,&nbsp;faqat&nbsp;oʻzini&nbsp;ayblash.</li><li>Kognitiv&nbsp;ildizi:&nbsp;Shaxsiy&nbsp;masʼuliyat&nbsp;chegaralarining&nbsp;buzilishi&nbsp;va&nbsp;giper-masʼuliyat&nbsp;.</li></ul></li><li><strong>Xafagarchilik&nbsp;va&nbsp;gʻazab:</strong><ul><li>Rahbariyat,&nbsp;hamkasblar&nbsp;yoki&nbsp;oʻquvchilarning&nbsp;xatti-harakatlaridan&nbsp;doimiy&nbsp;narozilik&nbsp;va&nbsp;buni&nbsp;miyada&nbsp;surunkali&nbsp;aylantirish&nbsp;(<em>rumination</em>).</li><li>Kognitiv&nbsp;ildizi:&nbsp;Boshqalarga&nbsp;nisbatan&nbsp;haqiqatga&nbsp;mos&nbsp;kelmaydigan&nbsp;kutuvlar.</li></ul></li></ol><h2>2.&nbsp;Kognitiv-xulq-atvor&nbsp;psixologiyasida&nbsp;ABC&nbsp;modeli</h2><p>Patogen&nbsp;fikrlarni&nbsp;anglash&nbsp;va&nbsp;ularni&nbsp;oʻzgartirishda&nbsp;Albert&nbsp;Ellis&nbsp;tomonidan&nbsp;ishlab&nbsp;chiqilgan&nbsp;<strong>ABC&nbsp;modeli</strong>&nbsp;eng&nbsp;samarali&nbsp;psixologik&nbsp;vosita&nbsp;hisoblanadi:</p><p></p><ul><li><strong>A&nbsp;(Activating&nbsp;Event&nbsp;—&nbsp;Qoʻzgʻatuvchi&nbsp;voqea):</strong>&nbsp;Tashqi&nbsp;muhitdagi&nbsp;real&nbsp;holat&nbsp;(Masalan:&nbsp;<em>Biologiya&nbsp;darsida&nbsp;virtual&nbsp;laboratoriya&nbsp;dasturi&nbsp;qotib&nbsp;qoldi</em>).</li><li><strong>B&nbsp;(Beliefs&nbsp;—&nbsp;Eʼtiqod&nbsp;va&nbsp;fikrlar):</strong>&nbsp;Oʻqituvchining&nbsp;bu&nbsp;voqeaga&nbsp;nisbatan&nbsp;kognitiv&nbsp;talqini.<ul><li><em>Patogen&nbsp;fikr&nbsp;(B1):</em>&nbsp;&quot;Dars&nbsp;rasvo&nbsp;boʻldi,&nbsp;men&nbsp;texnologiyani&nbsp;umuman&nbsp;tushunmayman!&quot;</li><li><em>Sanogen&nbsp;fikr&nbsp;(B2):</em>&nbsp;&quot;Dastur&nbsp;qotgani&nbsp;texnik&nbsp;holat,&nbsp;bu&nbsp;mening&nbsp;kasbiy&nbsp;mahoratimni&nbsp;belgilamaydi.&nbsp;B&nbsp;plan&nbsp;bor.&quot;</li></ul></li><li><strong>C&nbsp;(Consequences&nbsp;—&nbsp;Oqibatlar):</strong>&nbsp;Fikr&nbsp;(B)&nbsp;natijasida&nbsp;kelib&nbsp;chiqadigan&nbsp;emotsiya&nbsp;va&nbsp;harakat.<ul><li><em>Patogen&nbsp;oqibat&nbsp;(C1):</em>&nbsp;Vahima,&nbsp;gʻazab,&nbsp;qoʻllarning&nbsp;qaltirashi,&nbsp;dars&nbsp;unumdorligining&nbsp;yoʻqolishi.</li><li><em>Sanogen&nbsp;oqibat&nbsp;(C2):</em>&nbsp;Xotirjamlik,&nbsp;doskada&nbsp;tushuntirishga&nbsp;oʻtish,&nbsp;oʻquvchilar&nbsp;bilan&nbsp;muammoli&nbsp;muloqot.</li></ul></li></ul><blockquote><strong>Muhim&nbsp;saboq:</strong>&nbsp;Bizni&nbsp;voqeaning&nbsp;oʻzi&nbsp;(A)&nbsp;emas,&nbsp;balki&nbsp;voqea&nbsp;haqidagi&nbsp;fikrlarimiz&nbsp;(B)&nbsp;asabiylashtiradi&nbsp;va&nbsp;stressga&nbsp;soladi!</blockquote><h2>3.&nbsp;Refreyming&nbsp;texnikasi&nbsp;va&nbsp;kognitiv&nbsp;qayta&nbsp;tuzilish&nbsp;</h2><p><strong>Refreyming</strong>&nbsp;(ingl.&nbsp;<em>frame</em>&nbsp;—&nbsp;ramka)&nbsp;—&nbsp;bu&nbsp;salbiy&nbsp;yoki&nbsp;patogen&nbsp;vaziyatga&nbsp;berilgan&nbsp;maʼno&nbsp;va&nbsp;kognitiv&nbsp;ramkani&nbsp;oʻzgartirib,&nbsp;uni&nbsp;konstruktiv&nbsp;va&nbsp;sanogen&nbsp;shaklda&nbsp;qayta&nbsp;baholash&nbsp;texnikasidir.</p><p>Refreyming&nbsp;oʻtkazish&nbsp;bosqichlari:</p><ol><li><strong>Patogen&nbsp;ramkani&nbsp;ushlash:</strong>&nbsp;Oʻzingizga&nbsp;berayotgan&nbsp;salbiy&nbsp;va&nbsp;absolyut&nbsp;bahoni&nbsp;aniqlang&nbsp;(<em>&quot;Men&nbsp;hech&nbsp;qachon&nbsp;bu&nbsp;dasturni&nbsp;oʻrganolmayman&quot;</em>).</li><li><strong>Dalillarni&nbsp;tekshirish:</strong>&nbsp;Ushbu&nbsp;fikr&nbsp;100%&nbsp;haqiqatmi?&nbsp;Menda&nbsp;oʻrganish&nbsp;tajribasi&nbsp;boʻlganmi?</li><li><strong>Sanogen&nbsp;ramka&nbsp;yaratish:</strong>&nbsp;Vaziyatga&nbsp;rivojlanish&nbsp;nuqtai&nbsp;nazaridan&nbsp;baho&nbsp;berish&nbsp;(<em>&quot;Hozir&nbsp;murakkablik&nbsp;bor,&nbsp;lekin&nbsp;bu&nbsp;oʻrganish&nbsp;jarayonining&nbsp;tabiiy&nbsp;qismi.&nbsp;Bir&nbsp;nechta&nbsp;mashqdan&nbsp;keyin&nbsp;oʻzlashtiraman&quot;</em>).</li></ol><h2>4.&nbsp;Biologiya&nbsp;oʻqituvchisining&nbsp;kasbiy&nbsp;amaliyotida&nbsp;refreyming&nbsp;misollari</h2><table style=\"border: 1px solid #000;\"><tbody><tr><td data-row=\"1\"><strong>Patogen&nbsp;vaziyat&nbsp;va&nbsp;fikr</strong></td><td data-row=\"1\"><strong>Kognitiv&nbsp;xato&nbsp;turi</strong></td><td data-row=\"1\"><strong>Sanogen&nbsp;refreyming&nbsp;(Qayta&nbsp;baholash)</strong></td></tr><tr><td data-row=\"2\"><em>&quot;Oʻquvchilar&nbsp;virtual&nbsp;laboratoriya&nbsp;topshirigʻini&nbsp;bajara&nbsp;olishmadi,&nbsp;men&nbsp;yomon&nbsp;oʻqituvchiman.&quot;</em></td><td data-row=\"2\">Fojialashtirish,&nbsp;Shaxsiylashtirish</td><td data-row=\"2\"><em>&quot;Raqamli&nbsp;vositani&nbsp;oʻzlashtirish&nbsp;vaqt&nbsp;talab&nbsp;etadi.&nbsp;Bu&nbsp;mening&nbsp;yomonligim&nbsp;emas,&nbsp;yoʻriqnomani&nbsp;soddalashtirish&nbsp;uchun&nbsp;imkoniyat.&quot;</em></td></tr><tr><td data-row=\"3\"><em>&quot;3D&nbsp;modellar&nbsp;bilan&nbsp;dars&nbsp;oʻtishga&nbsp;koʻp&nbsp;vaqt&nbsp;ketyapti,&nbsp;unumli&nbsp;emas.&quot;</em></td><td data-row=\"3\">Kognitiv&nbsp;yopiqlik</td><td data-row=\"3\"><em>&quot;Yangi&nbsp;metodga&nbsp;moslashishda&nbsp;vaqt&nbsp;sarflanishi&nbsp;tabiiy.&nbsp;Koʻnikma&nbsp;shakllangach,&nbsp;bu&nbsp;dars&nbsp;sifatini&nbsp;2&nbsp;barobar&nbsp;oshiradi.&quot;</em></td></tr><tr><td data-row=\"4\"><em>&quot;Hamkasbim&nbsp;platformada&nbsp;mendan&nbsp;tez&nbsp;va&nbsp;zoʻr&nbsp;dars&nbsp;ishlanmasi&nbsp;tuzdi.&quot;</em></td><td data-row=\"4\">Solishtirish,&nbsp;Hasad</td><td data-row=\"4\"><em>&quot;Uning&nbsp;tajribasi&nbsp;menga&nbsp;namuna&nbsp;boʻla&nbsp;oladi.&nbsp;Undan&nbsp;qaysi&nbsp;usullardan&nbsp;foydalanganini&nbsp;soʻrab&nbsp;oʻrganaman.&quot;</em></td></tr></tbody></table><h3>M-2&nbsp;Maʼruza&nbsp;boʻyicha&nbsp;xulosa</h3><p>Patogen&nbsp;tafakkur&nbsp;—&nbsp;bu&nbsp;oʻqituvchining&nbsp;psixologik&nbsp;quvvatini&nbsp;soʻradigan&nbsp;kognitiv&nbsp;tuzilmadir.&nbsp;ABC&nbsp;modeli&nbsp;va&nbsp;refreyming&nbsp;texnikasini&nbsp;egallash&nbsp;orqali&nbsp;biologiya&nbsp;oʻqituvchisi&nbsp;salbiy&nbsp;fikrlash&nbsp;naqshlarini&nbsp;oʻz&nbsp;vaqtida&nbsp;payqaydi&nbsp;va&nbsp;ularni&nbsp;sanogen,&nbsp;yaʼni&nbsp;konstruktiv&nbsp;va&nbsp;rivojlantiruvchi&nbsp;tafakkurga&nbsp;aylantira&nbsp;oladi.</p>', NULL, 'http://127.0.0.1:8000/storage/presentations/1784925844_2-Modul__Patogen_Tafakkur_va_O_zgartirish_Texnikalari.pptx', 2, '2026-07-24 15:29:35', '2026-07-24 15:45:13'),
(11, 4, 'RAQAMLI TA’LIM MUHITIDA SANOGEN TAFAKKURNI RIVOJLANTIRISHNING METODIK TEXNOLOGIYALARI VA PEDAGOGIK SHART-SHAROITLARI', '<h1>RAQAMLI&nbsp;TA’LIM&nbsp;MUHITIDA&nbsp;SANOGEN&nbsp;TAFAKKURNI&nbsp;RIVOJLANTIRISHNING&nbsp;METODIK&nbsp;TEXNOLOGIYALARI&nbsp;VA&nbsp;PEDAGOGIK&nbsp;SHART-SHAROITLARI</h1><p><strong>Oʻquv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;maʼruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;oʻqituvchilarida&nbsp;raqamli&nbsp;taʼlim&nbsp;vositalari&nbsp;(3D&nbsp;modellar,&nbsp;virtual&nbsp;laboratoriyalar,&nbsp;interaktiv&nbsp;platformalar)&nbsp;bilan&nbsp;ishlash&nbsp;jarayonida&nbsp;sanogen&nbsp;tafakkurni&nbsp;amaliyotga&nbsp;tatbiq&nbsp;etishning&nbsp;metodik&nbsp;usullarini,&nbsp;metakognitiv&nbsp;oʻz-oʻzini&nbsp;boshqarish&nbsp;va&nbsp;kasbiy&nbsp;yonib&nbsp;bitish&nbsp;(<em>burnout</em>)&nbsp;profilaktikasi&nbsp;texnologiyalarini&nbsp;shakllantirish.</p><h2>1.&nbsp;Raqamli&nbsp;biologiya&nbsp;darslarida&nbsp;kognitiv&nbsp;toʻsiqlarni&nbsp;yengishning&nbsp;metodik&nbsp;strategiyalari</h2><p>Raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;biologik&nbsp;hodisa&nbsp;va&nbsp;jarayonlarni&nbsp;(masalan,&nbsp;hujayra&nbsp;boʻlinishi,&nbsp;oqsillar&nbsp;biosintezi,&nbsp;genetik&nbsp;muhandislik)&nbsp;interaktiv&nbsp;koʻrinishda&nbsp;tushuntirish&nbsp;yuqori&nbsp;pedagogik&nbsp;va&nbsp;texnik&nbsp;mahoratni&nbsp;talab&nbsp;etadi.&nbsp;Ushbu&nbsp;jarayonda&nbsp;oʻqituvchilarda&nbsp;yuzaga&nbsp;keladigan&nbsp;kognitiv&nbsp;va&nbsp;psixologik&nbsp;toʻsiqlarni&nbsp;yengish&nbsp;uchun&nbsp;quyidagi&nbsp;metodik&nbsp;strategiyalar&nbsp;qoʻllaniladi:</p><ol><li><strong>Bosqichma-bosqich&nbsp;moslashish&nbsp;strategiyasi:</strong><ul><li>Raqamli&nbsp;va&nbsp;3D&nbsp;vositalarni&nbsp;darsga&nbsp;birdaniga&nbsp;emas,&nbsp;balki&nbsp;kichik&nbsp;komponentlar&nbsp;holida&nbsp;(masalan,&nbsp;dastlab&nbsp;3-5&nbsp;daqiqalik&nbsp;qisqa&nbsp;simulyatsiya)&nbsp;kiritib&nbsp;borish.</li><li>Bu&nbsp;oʻqituvchidagi&nbsp;texnofobiya&nbsp;hamda&nbsp;surunkali&nbsp;xavotirlik&nbsp;darajasini&nbsp;pasaytiradi.</li></ul></li><li><strong>Muammoli-psixologik&nbsp;ssenariylashtirish:</strong><ul><li>Dars&nbsp;rejasini&nbsp;tuzishda&nbsp;har&nbsp;bir&nbsp;raqamli&nbsp;bosqich&nbsp;uchun&nbsp;ehtimoliy&nbsp;texnik&nbsp;yoki&nbsp;metodik&nbsp;nosozliklarni&nbsp;hisobga&nbsp;olish&nbsp;va&nbsp;oldindan&nbsp;ikkilamchi&nbsp;(zaxira)&nbsp;rejani&nbsp;shakllantirish.</li></ul></li><li><strong>Didaktik&nbsp;refreyming:</strong><ul><li>Raqamli&nbsp;texnologiyani&nbsp;darsning&nbsp;asosiy&nbsp;maqsadi&nbsp;emas,&nbsp;balki&nbsp;biologik&nbsp;tushunchalarni&nbsp;anglashni&nbsp;osonlashtiruvchi&nbsp;<strong>didaktik&nbsp;vosita</strong>&nbsp;sifatida&nbsp;idrok&nbsp;etish.</li></ul></li></ol><h2>2.&nbsp;Virtual&nbsp;laboratoriyalar&nbsp;va&nbsp;3D&nbsp;modellashtirishda&nbsp;sanogen&nbsp;refleksiya</h2><p>Virtual&nbsp;laboratoriya&nbsp;va&nbsp;3D&nbsp;modellar&nbsp;bilan&nbsp;ishlash&nbsp;jarayonida&nbsp;oʻqituvchi&nbsp;oʻquvchilar&nbsp;bilan&nbsp;muloqotda&nbsp;va&nbsp;texnika&nbsp;bilan&nbsp;ishlashda&nbsp;oʻz&nbsp;emotsional&nbsp;barqarorligini&nbsp;saqlashi&nbsp;uchun&nbsp;sanogen&nbsp;refleksiyaning&nbsp;quyidagi&nbsp;pedagogik&nbsp;mexanizmlaridan&nbsp;foydalanadi:</p><pre data-language=\"plain\">\n┌────────────────────────────────────────────────────────────────────────┐\n│               RAQAMLI DARSDAGI SANOGEN REFLEKSIYA BOSQICHLARI          │\n└───────────────────────────────────┬────────────────────────────────────┘\n                                    │\n ┌──────────────────────────────────┴──────────────────────────────────┐\n │ 1. Vaziyatni xolis qabul qilish (&quot;Texnik holat — darsning bir qismi&quot;)│\n ├─────────────────────────────────────────────────────────────────────┤\n │ 2. Oʻz-oʻziga emotsional baho berishni toʻxtatish (Aybdorlikni yoʻqotish)│\n ├─────────────────────────────────────────────────────────────────────┤\n │ 3. Dars dinamikasini moslashtirish (Interaktiv muloqot va savol-javob)│\n ├─────────────────────────────────────────────────────────────────────┤\n │ 4. Konstruktiv xulosa chiqarish (Metodikani takomillashtirish imkoni)│\n └─────────────────────────────────────────────────────────────────────┘\n</pre><h2>3.&nbsp;Biologiya&nbsp;oʻqituvchisining&nbsp;emotsional&nbsp;barqarorligi&nbsp;va&nbsp;kasbiy&nbsp;yonib&nbsp;bitish&nbsp;profilaktikasi</h2><p>Raqamli&nbsp;taʼlim&nbsp;muhitidagi&nbsp;intensiv&nbsp;axborot&nbsp;oqimi&nbsp;oʻqituvchidan&nbsp;doimiy&nbsp;diqqatni&nbsp;jamlashni&nbsp;talab&nbsp;qiladi.&nbsp;Sanogen&nbsp;tafakkur&nbsp;kasbiy&nbsp;yonib&nbsp;bitish&nbsp;(<em>burnout&nbsp;syndrome</em>)ning&nbsp;oldini&nbsp;olishda&nbsp;asosiy&nbsp;psixologik&nbsp;qalqon&nbsp;vazifasini&nbsp;oʻtaydi:</p><ul><li><strong>Inkorotmatsiyadan&nbsp;saqlanish&nbsp;(Axborot&nbsp;giper-yuklamasini&nbsp;saralash):</strong>&nbsp;Dars&nbsp;uchun&nbsp;zaruriy&nbsp;biologik&nbsp;va&nbsp;raqamli&nbsp;resurslarni&nbsp;qatʼiy&nbsp;kriteriyalar&nbsp;boʻyicha&nbsp;saralash&nbsp;(<em>Axborot&nbsp;selektivligi</em>).</li><li><strong>Emotsional&nbsp;gomeostazni&nbsp;tiklash:</strong>&nbsp;Darsdan&nbsp;tashqari&nbsp;vaqtda&nbsp;aqliy&nbsp;hamda&nbsp;psixologik&nbsp;zoʻriqishlarni&nbsp;yechuvchi&nbsp;refleksiv&nbsp;mashqlarni&nbsp;bajarish.</li><li><strong>Muvaffaqiyatlar&nbsp;kundaligi:</strong>&nbsp;Kichik&nbsp;kasbiy&nbsp;va&nbsp;raqamli&nbsp;yutuqlarni&nbsp;muntazam&nbsp;ravishda&nbsp;qayd&nbsp;etib&nbsp;borish&nbsp;orqali&nbsp;ichki&nbsp;motivatsiyani&nbsp;barqarorlashtirish.</li></ul><h2>4.&nbsp;Raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;sanogen&nbsp;tafakkurni&nbsp;rivojlantirishning&nbsp;pedagogik&nbsp;shart-sharoitlari</h2><p>Oʻqituvchida&nbsp;sanogen&nbsp;tafakkurning&nbsp;barqaror&nbsp;rivojlanishini&nbsp;taʼminlash&nbsp;uchun&nbsp;quyidagi&nbsp;<strong>3&nbsp;ta&nbsp;pedagogik&nbsp;shart-sharoit</strong>&nbsp;yaratilishi&nbsp;zarur:</p><ol><li><strong>Kognitiv-refleksiv&nbsp;muhitni&nbsp;yaratish:</strong>&nbsp;Oʻqituvchining&nbsp;oʻz&nbsp;faoliyatidagi&nbsp;xatolardan&nbsp;qoʻrqmasdan,&nbsp;ularni&nbsp;ilmiy&nbsp;va&nbsp;metodik&nbsp;tahlil&nbsp;qila&nbsp;olish&nbsp;imkoniyatining&nbsp;mavjudligi.</li><li><strong>Raqamli-didaktik&nbsp;qoʻllab-quvvatlov:</strong>&nbsp;Biologik&nbsp;3D&nbsp;modellar,&nbsp;virtual&nbsp;simulyatsiyalar&nbsp;va&nbsp;interaktiv&nbsp;dasturlar&nbsp;bilan&nbsp;ishlash&nbsp;boʻyicha&nbsp;aniq,&nbsp;soddalashtirilgan&nbsp;yoʻriqnomalarning&nbsp;yaratilganligi.</li><li><strong>Metakognitiv&nbsp;monitoring:</strong>&nbsp;Oʻqituvchi&nbsp;sanogen&nbsp;tafakkurining&nbsp;5&nbsp;ta&nbsp;subshkalasi&nbsp;(Refleksivlik,&nbsp;Kognitiv&nbsp;moslashuvchanlik,&nbsp;Emotsional&nbsp;regulyatsiya,&nbsp;Konstruktiv&nbsp;faollik,&nbsp;Axborot&nbsp;selektivligi)&nbsp;oʻsish&nbsp;dinamikasini&nbsp;batafsil&nbsp;kuzatib&nbsp;borish.</li></ol><h3>Maʼruza&nbsp;boʻyicha&nbsp;xulosa</h3><p>Raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;biologiya&nbsp;oʻqituvchisining&nbsp;sanogen&nbsp;tafakkurini&nbsp;rivojlantirish&nbsp;faqatgina&nbsp;nazariy&nbsp;bilimlarni&nbsp;oʻzlashtirish&nbsp;bilan&nbsp;cheklanmaydi.&nbsp;U&nbsp;oʻqituvchining&nbsp;har&nbsp;bir&nbsp;dars&nbsp;jarayonida,&nbsp;xususan&nbsp;virtual&nbsp;laboratoriyalar&nbsp;va&nbsp;3D&nbsp;texnologiyalar&nbsp;bilan&nbsp;ishlashdagi&nbsp;emotsional&nbsp;xotirjamligi,&nbsp;metakognitiv&nbsp;oʻz-oʻzini&nbsp;idora&nbsp;qilishi&nbsp;hamda&nbsp;elastik&nbsp;fikrlashi&nbsp;orqali&nbsp;amaliyotda&nbsp;namoyon&nbsp;boʻladi.</p>', '', '/storage/presentations/1784928100_3-Modul__Raqamli_Ta_lim_Muhitida_Sanogen_Tafakkur.pptx', 3, '2026-07-24 15:53:36', '2026-07-24 16:21:40'),
(12, 4, 'RAQAMLI TA’LIM MUHITIDA SANOGEN TAFAKKURNI TASHXIS QILISH, BAHOLASH VA MONITORING QILISH TEXNOLOGIYALARI', '<h1>RAQAMLI&nbsp;TA’LIM&nbsp;MUHITIDA&nbsp;SANOGEN&nbsp;TAFAKKURNI&nbsp;TASHXIS&nbsp;QILISH,&nbsp;BAHOLASH&nbsp;VA&nbsp;MONITORING&nbsp;QILISH&nbsp;TEXNOLOGIYALARI</h1><p><strong>Oʻquv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;maʼruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;oʻqituvchilarida&nbsp;raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;sanogen&nbsp;tafakkur&nbsp;darajasini&nbsp;aniqlash&nbsp;(tashxis&nbsp;qilish),&nbsp;natijalarni&nbsp;mezonlar&nbsp;boʻyicha&nbsp;baholash&nbsp;va&nbsp;kasbiy-psixologik&nbsp;rivojlanish&nbsp;dinamikasini&nbsp;muntazam&nbsp;kuzatib&nbsp;borish&nbsp;(monitoring)&nbsp;koʻnikmalarini&nbsp;shakllantirish.</p><h2>1.&nbsp;Sanogen&nbsp;tafakkurni&nbsp;tashxis&nbsp;qilishning&nbsp;metodik&nbsp;va&nbsp;psixologik&nbsp;asoslari</h2><p>Oʻqituvchining&nbsp;raqamli&nbsp;taʼlim&nbsp;muhitidagi&nbsp;ruhiy&nbsp;holati&nbsp;va&nbsp;fikrlash&nbsp;usulini&nbsp;aniqlash&nbsp;kasbiy&nbsp;rivojlanishning&nbsp;muhim&nbsp;bosqichidir.&nbsp;Tashxis&nbsp;jarayoni&nbsp;oʻqituvchining&nbsp;darsdagi&nbsp;kutilmagan&nbsp;murakkabliklar,&nbsp;texnik&nbsp;uzilishlar&nbsp;hamda&nbsp;axborot&nbsp;koʻpligiga&nbsp;boʻlgan&nbsp;munosabatini&nbsp;xolis&nbsp;oʻrganishga&nbsp;qaratilgan.</p><ol><li><strong>Oʻz-oʻzini&nbsp;kuzatish&nbsp;va&nbsp;baholash&nbsp;Soʻrovnomalari:</strong><ul><li>Oʻqituvchining&nbsp;fikrlash&nbsp;naqshlarini&nbsp;(patogen&nbsp;va&nbsp;sanogen&nbsp;nisbatini)&nbsp;aniqlashga&nbsp;xizmat&nbsp;qiluvchi&nbsp;maxsus&nbsp;metodik&nbsp;soʻrovnomalar.</li></ul></li><li><strong>Pedagogik&nbsp;vaziyatlarni&nbsp;tahlil&nbsp;qilish&nbsp;(Ssenariyli&nbsp;metodlar):</strong><ul><li>Dars&nbsp;jarayonida&nbsp;yuzaga&nbsp;keladigan&nbsp;muammoli&nbsp;holatlar&nbsp;aks&nbsp;etgan&nbsp;topshiriqlar&nbsp;orqali&nbsp;oʻqituvchining&nbsp;emotsional&nbsp;va&nbsp;kognituv&nbsp;reaksiyasini&nbsp;baholash.</li></ul></li></ol><h2>2.&nbsp;Sanogen&nbsp;tafakkurning&nbsp;5&nbsp;ta&nbsp;subshkalasi&nbsp;boʻyicha&nbsp;baholash&nbsp;mezonlari</h2><p>Sanogen&nbsp;tafakkur&nbsp;darajasi&nbsp;quyidagi&nbsp;<strong>5&nbsp;ta&nbsp;yoʻnalish&nbsp;(subshkala)</strong>&nbsp;boʻyicha&nbsp;baholanadi:</p><ul><li><strong>1.&nbsp;Refleksivlik&nbsp;(Oʻz-oʻzini&nbsp;tahlil&nbsp;qilish):</strong>&nbsp;Oʻqituvchining&nbsp;oʻz&nbsp;fikrlari&nbsp;va&nbsp;emotsiyalarini&nbsp;xolis&nbsp;baholay&nbsp;olish&nbsp;va&nbsp;xatolardan&nbsp;toʻgʻri&nbsp;xulosa&nbsp;chiqara&nbsp;olish&nbsp;darajasi.</li><li><strong>2.&nbsp;Kognitiv&nbsp;moslashuvchanlik&nbsp;(Fikr&nbsp;elastikligi):</strong>&nbsp;Kutilmagan&nbsp;dars&nbsp;holatlarida&nbsp;bir&nbsp;oʻquv&nbsp;yoʻnalishidan&nbsp;ikkinchisiga&nbsp;tez&nbsp;va&nbsp;asabiylashmasdan&nbsp;oʻta&nbsp;olish&nbsp;imkoniyati.</li><li><strong>3.&nbsp;Emotsional&nbsp;regulyatsiya&nbsp;(His-tuygʻularni&nbsp;boshqarish):</strong>&nbsp;Vahima,&nbsp;gʻazab&nbsp;va&nbsp;xavotirlikni&nbsp;toʻxtatib,&nbsp;ruhiy&nbsp;xotirjamlikni&nbsp;saqlab&nbsp;qolish&nbsp;qobiliyati.</li><li><strong>4.&nbsp;Konstruktiv&nbsp;faollik&nbsp;(Rivojlantiruvchi&nbsp;harakat):</strong>&nbsp;Muammo&nbsp;yuz&nbsp;berganda&nbsp;aybdorni&nbsp;qidirmasdan,&nbsp;darhol&nbsp;amaliy&nbsp;yechimga&nbsp;(zaxira&nbsp;rejasiga)&nbsp;oʻtish.</li><li><strong>5.&nbsp;Axborot&nbsp;selektivligi&nbsp;(Axborotni&nbsp;saralash):</strong>&nbsp;Keraksiz&nbsp;va&nbsp;ortiqcha&nbsp;raqamli&nbsp;maʼlumotlarni&nbsp;chetlashtirib,&nbsp;faqat&nbsp;dars&nbsp;uchun&nbsp;muhim&nbsp;resurslarni&nbsp;tanlab&nbsp;olish.</li></ul><h2>3.&nbsp;Baholash&nbsp;darajalari&nbsp;va&nbsp;koʻrsatkichlar</h2><p>Tashxis&nbsp;natijalariga&nbsp;koʻra&nbsp;oʻqituvchilar&nbsp;<strong>3&nbsp;ta&nbsp;daraja</strong>&nbsp;boʻyicha&nbsp;guruhlanadi:</p><pre data-language=\"plain\">\n┌────────────────────────────────────────────────────────────────────────┐\n│             SANOGEN TAFAKKURNI BAHOLASH DARAJALARI                     │\n└───────────────────────────────────┬────────────────────────────────────┘\n                                    │\n ┌──────────────────────────────────┴──────────────────────────────────┐\n │ 1. Yuqori (Barqaror-sanogen) daraja:                               │\n │    - Ruhiy muvozanat toʻliq saqlanadi, zaxira reja tezda qoʻllaniladi. │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 2. Oʻrta (Oʻtuvchi) daraja:                                         │\n │    - Dastlabki daqiqalarda biroz xavotir boʻladi, keyin tiklanadi.    │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 3. Quyi (Patogenga moyil) daraja:                                   │\n │    - Surunkali xavotir, aybdorlik hissi va fojialashtirish ustun.     │\n └─────────────────────────────────────────────────────────────────────┘\n</pre><h2>4.&nbsp;Kasbiy-psixologik&nbsp;monitoringni&nbsp;tashkil&nbsp;etish</h2><p>Monitoring&nbsp;—&nbsp;bu&nbsp;oʻqituvchining&nbsp;sanogen&nbsp;tafakkuri&nbsp;oʻsishini&nbsp;va&nbsp;kasbiy&nbsp;yonib&nbsp;bitish&nbsp;(<em>ruhiy&nbsp;charchash</em>)&nbsp;profilaktikasini&nbsp;muntazam&nbsp;va&nbsp;tizimli&nbsp;kuzatib&nbsp;borish&nbsp;jarayonidir.</p><ul><li><strong>Raqamli&nbsp;kuzatuv&nbsp;xaritasi:</strong>&nbsp;Har&nbsp;bir&nbsp;modul&nbsp;va&nbsp;darsdan&nbsp;soʻng&nbsp;oʻqituvchining&nbsp;ruhiy&nbsp;barqarorlik&nbsp;koʻrsatkichlarini&nbsp;jadval&nbsp;koʻrinishida&nbsp;qayd&nbsp;etish.</li><li><strong>Oʻz-oʻzini&nbsp;rivojlantirish&nbsp;trayektoriyasi:</strong>&nbsp;Tashxis&nbsp;natijalari&nbsp;asosida&nbsp;har&nbsp;bir&nbsp;oʻqituvchi&nbsp;uchun&nbsp;individual&nbsp;(shaxsiy)&nbsp;tavsiyalar&nbsp;va&nbsp;psixologik-Maʼruza&nbsp;boʻyicha&nbsp;xulosa</li></ul><p>Sanogen&nbsp;tafakkurni&nbsp;tashxis&nbsp;qilish&nbsp;va&nbsp;monitoring&nbsp;qilish&nbsp;oʻqituvchiga&nbsp;oʻzining&nbsp;kasbiy&nbsp;va&nbsp;ruhiy&nbsp;holatini&nbsp;xolis&nbsp;koʻrish&nbsp;imkonini&nbsp;beradi.&nbsp;Tizimli&nbsp;kuzatuv&nbsp;orqali&nbsp;biologiya&nbsp;oʻqituvchilari&nbsp;raqamli&nbsp;taʼlim&nbsp;muhitida&nbsp;ruhiy&nbsp;zoʻriqishlarsiz,&nbsp;yuqori&nbsp;metodik&nbsp;samaradorlik&nbsp;bilan&nbsp;faoliyat&nbsp;olib&nbsp;boradilar.</p>', '', '/storage/presentations/1784929066_4-Modul__Sanogen_Tafakkur_Kompetensiyasini_Baholash.pptx', 4, '2026-07-24 16:25:11', '2026-07-24 16:37:46'),
(13, 4, 'BIOLOGIYA O‘QITUVCHILARIDA SANOGEN TAFAKKURNI SHAKLLANTIRISHNING TIZIMLI-LOHIYAVIY MODELI VA INDIVIDUAL RIVOJLANISH TRAYEKTORIYASI', '<h1>BIOLOGIYA&nbsp;O‘QITUVCHILARIDA&nbsp;SANOGEN&nbsp;TAFAKKURNI&nbsp;SHAKLLANTIRISHNING&nbsp;TIZIMLI-LOHIYAVIY&nbsp;MODELI&nbsp;VA&nbsp;INDIVIDUAL&nbsp;RIVOJLANISH&nbsp;TRAYEKTORIYASI</h1><p><strong>O‘quv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;ma’ruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;o‘qituvchilarida&nbsp;sanogen&nbsp;tafakkurni&nbsp;rivojlantirishning&nbsp;tizimli-lohiyaviy&nbsp;modelini&nbsp;shakllantirish,&nbsp;shaxsiy&nbsp;rivojlanish&nbsp;trayektoriyasini&nbsp;loyihalashtirish&nbsp;hamda&nbsp;ta’lim&nbsp;sifatini&nbsp;oshirishda&nbsp;ushbu&nbsp;modelni&nbsp;amaliyotga&nbsp;tatbiq&nbsp;etish&nbsp;ko‘nikmalarini&nbsp;rivojlantirish.</p><h2>1.&nbsp;Sanogen&nbsp;tafakkurni&nbsp;rivojlantirishning&nbsp;tizimli-lohiyaviy&nbsp;modeli</h2><p>O‘qituvchilarda&nbsp;sanogen&nbsp;(sog‘lom&nbsp;va&nbsp;rivojlantiruvchi)&nbsp;tafakkurni&nbsp;shakllantirish&nbsp;tasodifiy&nbsp;emas,&nbsp;balki&nbsp;aniq&nbsp;<strong>tizimli-lohiyaviy&nbsp;yondashuv</strong>&nbsp;asosida&nbsp;amalga&nbsp;oshiriladi.&nbsp;Ushbu&nbsp;model&nbsp;4&nbsp;ta&nbsp;o‘zaro&nbsp;bog‘liq&nbsp;blokdan&nbsp;iborat:</p><ol><li><strong>Maqsadli&nbsp;blok:</strong><ul><li>Raqamli&nbsp;ta’lim&nbsp;muhitida&nbsp;biologiya&nbsp;o‘qituvchisining&nbsp;emotsional&nbsp;barqarorligini&nbsp;ta’minlash,&nbsp;kognitiv&nbsp;elastikligini&nbsp;oshirish&nbsp;va&nbsp;ruhiy&nbsp;charchashning&nbsp;oldini&nbsp;olish.</li></ul></li><li><strong>Mazmunli&nbsp;blok:</strong><ul><li>Sanogen&nbsp;tafakkurning&nbsp;5&nbsp;ta&nbsp;subshkalasi&nbsp;(Refleksivlik,&nbsp;Kognitiv&nbsp;moslashuvchanlik,&nbsp;Emotsional&nbsp;regulyatsiya,&nbsp;Konstruktiv&nbsp;faollik&nbsp;va&nbsp;Axborot&nbsp;selektivligi)&nbsp;va&nbsp;biologiya&nbsp;fanini&nbsp;o‘qitish&nbsp;xususiyatlarining&nbsp;birligi.</li></ul></li><li><strong>Texnologik-amaliy&nbsp;blok:</strong><ul><li>Interaktiv&nbsp;simulyatsiyalar,&nbsp;3D&nbsp;modellar,&nbsp;virtual&nbsp;laboratoriyalar,&nbsp;zaxira&nbsp;dars&nbsp;rejalari&nbsp;hamda&nbsp;qayta&nbsp;baholash&nbsp;amaliyotlarining&nbsp;dars&nbsp;jarayoniga&nbsp;tatbiq&nbsp;etilishi.</li></ul></li><li><strong>Natijaviy-baho&nbsp;bloki:</strong><ul><li>O‘qituvchining&nbsp;sanogen&nbsp;tafakkur&nbsp;ko‘rsatkichlari&nbsp;dinamikasini&nbsp;va&nbsp;dars&nbsp;samaradorligini&nbsp;tashxis&nbsp;qilish&nbsp;hamda&nbsp;monitoring&nbsp;qilib&nbsp;borish.</li></ul></li></ol><h2>2.&nbsp;O‘qituvchining&nbsp;individual&nbsp;(shaxsiy)&nbsp;rivojlanish&nbsp;trayektoriyasini&nbsp;loyihalashtirish</h2><p>Har&nbsp;bir&nbsp;biologiya&nbsp;o‘qituvchisi&nbsp;o‘zining&nbsp;kognitiv&nbsp;xususiyatlari,&nbsp;raqamli&nbsp;savodxonlik&nbsp;darajasi&nbsp;va&nbsp;emotsional&nbsp;holatidan&nbsp;kelib&nbsp;chiqib,&nbsp;<strong>shaxsiy&nbsp;rivojlanish&nbsp;trayektoriyasiga</strong>&nbsp;ega&nbsp;bo‘lishi&nbsp;kerak.</p><pre data-language=\"plain\">\n┌────────────────────────────────────────────────────────────────────────┐\n│             INDIVIDUAL RIVOJLANISH TRAYEKTORIYASI BOSQICHLARI          │\n└───────────────────────────────────┬────────────────────────────────────┘\n                                    │\n ┌──────────────────────────────────┴──────────────────────────────────┐\n │ 1. Dastlabki tashxis (Zaif va kuchli jihatlarni aniqlash)            │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 2. Shaxsiy maqsad va vazifalarni belgilash (Korreksiya yo‘nalishi)  │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 3. Amaliy-metodik mashqlarni bajarish (Zaxira reja, saralash)      │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 4. O‘z-o‘zini monitoring qilish (Refleksiv kundalik yuritish)       │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 5. Natijani qayta baholash va trayektoriyani moslashtirish          │\n └─────────────────────────────────────────────────────────────────────┘\n</pre><h2>3.&nbsp;Sanogen&nbsp;modelni&nbsp;biologiya&nbsp;darslari&nbsp;amaliyotiga&nbsp;tatbiq&nbsp;etish&nbsp;mexanizmlari</h2><p>Modelni&nbsp;amaliyotga&nbsp;joriy&nbsp;etishda&nbsp;biologiya&nbsp;o‘qituvchisi&nbsp;quyidagi&nbsp;<strong>3&nbsp;ta&nbsp;asosiy&nbsp;mexanizmga</strong>&nbsp;tayanadi:</p><ul><li><strong>1.&nbsp;Kognitiv&nbsp;qayta&nbsp;qurish&nbsp;mexanizmi:</strong>&nbsp;Darsdagi&nbsp;kutilmagan&nbsp;texnik&nbsp;va&nbsp;metodik&nbsp;muammolarni&nbsp;(masalan,&nbsp;internet&nbsp;uzilishi&nbsp;yoki&nbsp;tajriba&nbsp;dasturining&nbsp;ishlamay&nbsp;qolishi)&nbsp;salbiy&nbsp;hodisa&nbsp;sifatida&nbsp;emas,&nbsp;balki&nbsp;yangi&nbsp;pedagogik&nbsp;mahoratni&nbsp;egallash&nbsp;imkoniyati&nbsp;deb&nbsp;idrok&nbsp;etish.</li><li><strong>2.&nbsp;Metakognitiv&nbsp;boshqaruv&nbsp;mexanizmi:</strong>&nbsp;Dars&nbsp;davomida&nbsp;o‘zining&nbsp;his-tuyg‘ulari&nbsp;hamda&nbsp;fikrlarini&nbsp;nazorat&nbsp;qilish,&nbsp;keraksiz&nbsp;axborot&nbsp;yuklamasidan&nbsp;voz&nbsp;kechish&nbsp;va&nbsp;diqqatni&nbsp;asosiy&nbsp;didaktik&nbsp;maqsadga&nbsp;qaratish.</li><li><strong>3.&nbsp;Konstruktiv&nbsp;moslashuvchanlik&nbsp;mexanizmi:</strong>&nbsp;Texnik&nbsp;nosozlik&nbsp;yuz&nbsp;berganda&nbsp;vahimaga&nbsp;tushmay,&nbsp;darhol&nbsp;oldindan&nbsp;tayyorlab&nbsp;qo‘yilgan&nbsp;zaxira&nbsp;dars&nbsp;ssenariysiga&nbsp;(doskada&nbsp;ishlash,&nbsp;tarqatma&nbsp;materiallar,&nbsp;muammoli&nbsp;savol-javob)&nbsp;o‘tish.</li></ul><h2>4.&nbsp;Tizimli-lohiyaviy&nbsp;model&nbsp;samaradorligini&nbsp;baholash&nbsp;va&nbsp;kelgusi&nbsp;istiqbollar</h2><p>Sanogen&nbsp;tafakkurni&nbsp;shakllantirish&nbsp;modelining&nbsp;amaliyotdagi&nbsp;samaradorligi&nbsp;quyidagi&nbsp;<strong>natijaviy&nbsp;ko‘rsatkichlar</strong>&nbsp;orqali&nbsp;baholanadi:</p><ol><li><strong>O‘qituvchi&nbsp;ruhiy&nbsp;holatining&nbsp;barqarorlashuvi:</strong>&nbsp;Kasbiy&nbsp;yonib&nbsp;bitish&nbsp;(<em>ruhiy&nbsp;charchash</em>)&nbsp;hamda&nbsp;dars&nbsp;oldi&nbsp;xavotirligining&nbsp;sezilarli&nbsp;pasayishi.</li><li><strong>Dars&nbsp;sifatining&nbsp;oshishi:</strong>&nbsp;Raqamli&nbsp;va&nbsp;an’anaviy&nbsp;metodlarning&nbsp;optimal&nbsp;uyg‘unlashuvi&nbsp;natijasida&nbsp;o‘quvchilarning&nbsp;biologiya&nbsp;fanini&nbsp;o‘zlashtirish&nbsp;ko‘rsatkichi&nbsp;yuksalishi.</li><li><strong>Metodik&nbsp;moslashuvchanlik:</strong>&nbsp;O‘qituvchining&nbsp;har&nbsp;qanday&nbsp;kutilmagan&nbsp;vaziyatda&nbsp;metodik&nbsp;xotirjamlikni&nbsp;va&nbsp;yuqori&nbsp;pedagogik&nbsp;mahoratni&nbsp;namoyon&nbsp;eta&nbsp;olishi.</li></ol><h3>Ma’ruza&nbsp;bo‘yicha&nbsp;xulosa</h3><p>Biologiya&nbsp;o‘qituvchilarida&nbsp;sanogen&nbsp;tafakkurni&nbsp;shakllantirishning&nbsp;tizimli-lohiyaviy&nbsp;modeli&nbsp;va&nbsp;shaxsiy&nbsp;rivojlanish&nbsp;trayektoriyasi&nbsp;—&nbsp;o‘qituvchining&nbsp;raqamli&nbsp;ta’lim&nbsp;muhitidagi&nbsp;kasbiy&nbsp;barqarorligi&nbsp;va&nbsp;ruhiy&nbsp;salomatligining&nbsp;kafolatidir.&nbsp;Ushbu&nbsp;model&nbsp;o‘qituvchiga&nbsp;har&nbsp;qanday&nbsp;metodik&nbsp;va&nbsp;texnik&nbsp;murakkabliklarni&nbsp;oson&nbsp;yengib,&nbsp;samarali&nbsp;ta’lim&nbsp;jarayonini&nbsp;tashkil&nbsp;etish&nbsp;imkonini&nbsp;beradi.</p>', '', '/storage/presentations/1784930359_Presentation1.ppt', 5, '2026-07-24 16:41:21', '2026-07-24 16:59:19'),
(14, 4, 'BIOLOGIYA O‘QITUVCHILARIDA SANOGEN TAFAKKURNI SHAKLLANTIRISHNING AMALIY-PEDAGOGIK SAMARADORLIGI VA TAJRIBA-SINOV ISA HISOBLARI', '<h1>BIOLOGIYA&nbsp;O‘QITUVCHILARIDA&nbsp;SANOGEN&nbsp;TAFAKKURNI&nbsp;SHAKLLANTIRISHNING&nbsp;AMALIY-PEDAGOGIK&nbsp;SAMARADORLIGI&nbsp;VA&nbsp;TAJRIBA-SINOV&nbsp;ISA&nbsp;HISOBLARI</h1><p><strong>O‘quv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;ma’ruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;o‘qituvchilarida&nbsp;sanogen&nbsp;tafakkurni&nbsp;shakllantirish&nbsp;bo‘yicha&nbsp;o‘tkazilgan&nbsp;tajriba-sinov&nbsp;ishlari&nbsp;natijalarini&nbsp;matematik-statistik&nbsp;tahlil&nbsp;qilish,&nbsp;amaliy-pedagogik&nbsp;samaradorlikni&nbsp;baholash&nbsp;hamda&nbsp;dissertatsiya&nbsp;tadqiqoti&nbsp;bo‘yicha&nbsp;yakuniy&nbsp;ilmiy-metodik&nbsp;tavsiyalarni&nbsp;shakllantirish.</p><h2>1.&nbsp;Tajriba-sinov&nbsp;ishlarining&nbsp;metodikasi&nbsp;va&nbsp;tashkiliy&nbsp;bosqichlari</h2><p>Sanogen&nbsp;tafakkurni&nbsp;rivojlantirish&nbsp;modelining&nbsp;amaliy&nbsp;samaradorligini&nbsp;isbotlash&nbsp;maqsadida&nbsp;tajriba-sinov&nbsp;ishlari&nbsp;<strong>3&nbsp;ta&nbsp;bosqichda</strong>&nbsp;tashkil&nbsp;etildi:</p><ol><li><strong>Aniqlovchi&nbsp;bosqich:</strong><ul><li>Tajriba&nbsp;va&nbsp;nazorat&nbsp;guruhlaridagi&nbsp;biologiya&nbsp;o‘qituvchilarining&nbsp;dastlabki&nbsp;sanogen&nbsp;tafakkur&nbsp;darajalari,&nbsp;emotsional&nbsp;barqarorligi&nbsp;hamda&nbsp;raqamli&nbsp;vositalar&nbsp;bilan&nbsp;ishlashdagi&nbsp;xavotirlik&nbsp;ko‘rsatkichlari&nbsp;tashxis&nbsp;qilindi.</li></ul></li><li><strong>Shakllantiruvchi&nbsp;bosqich:</strong><ul><li>Tajriba&nbsp;guruhida&nbsp;sanogen&nbsp;tafakkurni&nbsp;shakllantirishning&nbsp;tizimli-lohiyaviy&nbsp;modeli,&nbsp;shaxsiy&nbsp;rivojlanish&nbsp;trayektoriyalari&nbsp;va&nbsp;zaxira&nbsp;dars&nbsp;rejalari&nbsp;amaliyotga&nbsp;joriy&nbsp;etildi.&nbsp;Nazorat&nbsp;guruhida&nbsp;esa&nbsp;mashg‘ulotlar&nbsp;an’anaviy&nbsp;tarzda&nbsp;olib&nbsp;borildi.</li></ul></li><li><strong>Nazorat-yakunlovchi&nbsp;bosqich:</strong><ul><li>Tajriba-sinov&nbsp;mashg‘ulotlaridan&nbsp;so‘ng&nbsp;har&nbsp;ikkala&nbsp;guruh&nbsp;o‘qituvchilarida&nbsp;qayta&nbsp;tashxis&nbsp;o‘tkazilib,&nbsp;natijalar&nbsp;o‘zaro&nbsp;solishtirildi.</li></ul></li></ol><h2>2.&nbsp;Tajriba-sinov&nbsp;natijalarining&nbsp;matematik-statistik&nbsp;tahlili</h2><p>Tajriba&nbsp;va&nbsp;nazorat&nbsp;guruhlaridagi&nbsp;ijobiy&nbsp;o‘zgarishlarning&nbsp;tasodifiy&nbsp;emasligini&nbsp;hamda&nbsp;tadqiqot&nbsp;gipotezasining&nbsp;to‘g‘riligini&nbsp;isbotlash&nbsp;uchun&nbsp;<strong>Pirlsonning&nbsp;xiy-kvadrat&nbsp;($\\chi^2$)</strong>&nbsp;va&nbsp;<strong>Styudentning&nbsp;$t$-meyori</strong>&nbsp;kabi&nbsp;matematik-statistik&nbsp;usullardan&nbsp;foydalanildi.</p><table style=\"border: 1px solid #000;\"><tbody><tr><td data-row=\"1\"><strong>Ko‘rsatkichlar&nbsp;va&nbsp;subshkalar</strong></td><td data-row=\"1\"><strong>Dastlabki&nbsp;holat&nbsp;(Tajriba&nbsp;guruh)</strong></td><td data-row=\"1\"><strong>Yakuniy&nbsp;holat&nbsp;(Tajriba&nbsp;guruh)</strong></td><td data-row=\"1\"><strong>O‘sish&nbsp;dinamikasi&nbsp;(%)</strong></td></tr><tr><td data-row=\"2\"><strong>Refleksivlik&nbsp;(O‘z-o‘zini&nbsp;tahlil&nbsp;qilish)</strong></td><td data-row=\"2\">42.5%</td><td data-row=\"2\">78.2%</td><td data-row=\"2\"><strong>+35.7%</strong></td></tr><tr><td data-row=\"3\"><strong>Kognitiv&nbsp;moslashuvchanlik</strong></td><td data-row=\"3\">38.0%</td><td data-row=\"3\">81.5%</td><td data-row=\"3\"><strong>+43.5%</strong></td></tr><tr><td data-row=\"4\"><strong>Emotsional&nbsp;regulyatsiya</strong></td><td data-row=\"4\">45.1%</td><td data-row=\"4\">83.0%</td><td data-row=\"4\"><strong>+37.9%</strong></td></tr><tr><td data-row=\"5\"><strong>Konstruktiv&nbsp;faollik</strong></td><td data-row=\"5\">41.0%</td><td data-row=\"5\">85.4%</td><td data-row=\"5\"><strong>+44.4%</strong></td></tr><tr><td data-row=\"6\"><strong>Axborot&nbsp;selektivligi</strong></td><td data-row=\"6\">49.3%</td><td data-row=\"6\">80.1%</td><td data-row=\"6\"><strong>+30.8%</strong></td></tr></tbody></table><blockquote><strong>Matematik&nbsp;xulosa:</strong>&nbsp;Tajriba&nbsp;guruhida&nbsp;erishilgan&nbsp;natijalar&nbsp;statistik&nbsp;jihatdan&nbsp;ishonchli&nbsp;($p&nbsp;&lt;&nbsp;0.05$)&nbsp;bo‘lib,&nbsp;taklif&nbsp;etilgan&nbsp;modellarning&nbsp;amaliy&nbsp;samaradorligini&nbsp;to‘liq&nbsp;tasdiqladi.</blockquote><h2>3.&nbsp;O‘qituvchilar&nbsp;kasbiy&nbsp;faoliyatidagi&nbsp;amaliy&nbsp;va&nbsp;emotsional&nbsp;o‘zgarishlar</h2><p>Raqamli&nbsp;ta’lim&nbsp;muhitida&nbsp;sanogen&nbsp;tafakkur&nbsp;texnologiyasining&nbsp;tatbiq&nbsp;etilishi&nbsp;biologiya&nbsp;o‘qituvchilarida&nbsp;quyidagi&nbsp;sifat&nbsp;ko‘rsatkichlarini&nbsp;ta’minladi:</p><ul><li><strong>Emotsional&nbsp;zo‘riqishning&nbsp;pasayishi:</strong>&nbsp;Raqamli&nbsp;texnologiyalar&nbsp;va&nbsp;virtual&nbsp;laboratoriyalar&nbsp;bilan&nbsp;ishlashda&nbsp;yuzaga&nbsp;keladigan&nbsp;texnik&nbsp;nosozliklardan&nbsp;qo‘rqish&nbsp;xavotiri&nbsp;sezilarli&nbsp;darajada&nbsp;kamaydi.</li><li><strong>Kasbiy&nbsp;yonib&nbsp;bitish&nbsp;(<em>ruhiy&nbsp;charchash</em>)&nbsp;profilaktikasi:</strong>&nbsp;O‘qituvchilarda&nbsp;o‘z-o‘zini&nbsp;boshqarish&nbsp;va&nbsp;axborotni&nbsp;saralash&nbsp;ko‘nikmalari&nbsp;shakllanib,&nbsp;ruhiy&nbsp;barqarorlik&nbsp;yuksaldi.</li><li><strong>O‘quvchilar&nbsp;o‘zlashtirishining&nbsp;oshishi:</strong>&nbsp;O‘qituvchilarning&nbsp;darsdagi&nbsp;metodik&nbsp;xotirjamligi&nbsp;va&nbsp;moslashuvchanligi&nbsp;biologiya&nbsp;darslarining&nbsp;unumdorligi&nbsp;hamda&nbsp;ta’lim&nbsp;sifatini&nbsp;oshirdi.</li></ul><h2>4.&nbsp;Biologiya&nbsp;o‘qituvchilari&nbsp;va&nbsp;ta’lim&nbsp;muassasalari&nbsp;uchun&nbsp;ilmiy-metodik&nbsp;tavsiyalar</h2><p>Tajriba-sinov&nbsp;ishlari&nbsp;xulosalariga&nbsp;tayanib,&nbsp;quyidagi&nbsp;yakuniy&nbsp;<strong>ilmiy-metodik&nbsp;tavsiyalar</strong>&nbsp;ishlab&nbsp;chiqildi:</p><ol><li><strong>Malaka&nbsp;oshirish&nbsp;kurslariga&nbsp;joriy&nbsp;etish:</strong>&nbsp;Biologiya&nbsp;o‘qituvchilarining&nbsp;malakasini&nbsp;oshirish&nbsp;va&nbsp;ularni&nbsp;qayta&nbsp;tayyorlash&nbsp;dasturlariga&nbsp;&quot;Sanogen&nbsp;tafakkur&quot;&nbsp;modulini&nbsp;doimiy&nbsp;o‘quv&nbsp;bloki&nbsp;sifatida&nbsp;kiritish.</li><li><strong>Zaxira&nbsp;dars&nbsp;ssenariylarini&nbsp;standartlashtirish:</strong>&nbsp;Raqamli&nbsp;va&nbsp;3D&nbsp;texnologiyalarga&nbsp;asoslangan&nbsp;har&nbsp;bir&nbsp;biologik&nbsp;mavzu&nbsp;bo‘yicha&nbsp;muqobil&nbsp;(Plan&nbsp;B)&nbsp;metodik&nbsp;ishlanmalarni&nbsp;shakllantirish.</li><li><strong>Muntazam&nbsp;refleksiv&nbsp;kuzatuv:</strong>&nbsp;O‘qituvchilar&nbsp;faoliyatida&nbsp;shaxsiy&nbsp;rivojlanish&nbsp;trayektoriyasi&nbsp;hamda&nbsp;refleksiv&nbsp;kundaliklardan&nbsp;foydalanish&nbsp;amaliyotini&nbsp;keng&nbsp;ommalashtirish.</li></ol><h3>Ma’ruza&nbsp;bo‘yicha&nbsp;xulosa</h3><p>6-modul&nbsp;bo‘yicha&nbsp;o‘tkazilgan&nbsp;tajriba-sinov&nbsp;ishlari&nbsp;va&nbsp;ularning&nbsp;matematik-statistik&nbsp;tahlili&nbsp;sanogen&nbsp;tafakkurni&nbsp;shakllantirish&nbsp;modelining&nbsp;yuqori&nbsp;amaliy-pedagogik&nbsp;samaradorlikka&nbsp;ega&nbsp;ekanligini&nbsp;to‘liq&nbsp;ko‘rsatdi.&nbsp;Ushbu&nbsp;yondashuv&nbsp;biologiya&nbsp;o‘qituvchisining&nbsp;raqamli&nbsp;ta’lim&nbsp;muhitida&nbsp;ruhiy&nbsp;salomatligini&nbsp;saqlash&nbsp;va&nbsp;kasbiy&nbsp;mahoratini&nbsp;yuksaltirishning&nbsp;eng&nbsp;maqbul&nbsp;amaliy&nbsp;mexanizmidir.</p>', NULL, '/storage/presentations/1784931963_Presentation1.pptx', 6, '2026-07-24 17:00:18', '2026-07-24 17:26:03');
INSERT INTO `modules` (`id`, `course_id`, `title`, `content`, `video_url`, `presentation_url`, `order`, `created_at`, `updated_at`) VALUES
(15, 4, '\"SANOTAFEDU\" RAQAMLI PLATFORMASI INTEGRATSIYASI VA BIOLOGIYA O‘QITUVCHILARINING UZLUKSIZ O‘Z-O‘ZINI RIVOJLANTIRISH METODIKASI', '<h1>&quot;SANOTAFEDU&quot;&nbsp;RAQAMLI&nbsp;PLATFORMASI&nbsp;INTEGRATSIYASI&nbsp;VA&nbsp;BIOLOGIYA&nbsp;O‘QITUVCHILARINING&nbsp;UZLUKSIZ&nbsp;O‘Z-O‘ZINI&nbsp;RIVOJLANTIRISH&nbsp;METODIKASI</h1><p><strong>O‘quv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;ma’ruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;o‘qituvchilarida&nbsp;&quot;SanoTafEdu&quot;&nbsp;raqamli&nbsp;platformasi,&nbsp;sun’iy&nbsp;intellekt&nbsp;imkoniyatlari&nbsp;hamda&nbsp;o‘yinlashtirish&nbsp;(<em>gamifikatsiya</em>)&nbsp;texnologiyalaridan&nbsp;foydalanib,&nbsp;sanogen&nbsp;tafakkurni&nbsp;uzluksiz&nbsp;o‘z-o‘zini&nbsp;takomillashtirish&nbsp;va&nbsp;pedagogik&nbsp;faoliyatga&nbsp;tatbiq&nbsp;etish&nbsp;ko‘nikmalarini&nbsp;rivojlantirish.</p><h2>1.&nbsp;&quot;SanoTafEdu&quot;&nbsp;raqamli&nbsp;platformasining&nbsp;didaktik&nbsp;va&nbsp;psixologik&nbsp;salohiyati</h2><p>Raqamlashtirish&nbsp;davrida&nbsp;biologiya&nbsp;o‘qituvchisining&nbsp;sanogen&nbsp;tafakkurini&nbsp;rivojlantirish&nbsp;bevosita&nbsp;zamonaviy&nbsp;raqamli&nbsp;muhitni&nbsp;yaratish&nbsp;bilan&nbsp;bog‘liq.&nbsp;Ushbu&nbsp;ehtiyojdan&nbsp;kelib&nbsp;chiqib&nbsp;yaratilgan&nbsp;<strong>&quot;SanoTafEdu&quot;</strong>&nbsp;interaktiv&nbsp;raqamli&nbsp;platformasi&nbsp;o‘qituvchining&nbsp;kasbiy&nbsp;va&nbsp;ruhiy&nbsp;holatini&nbsp;doimiy&nbsp;qo‘llab-quvvatlashga&nbsp;xizmat&nbsp;qiladi.</p><ul><li><strong>Shaxsiy&nbsp;boshqaruv&nbsp;paneli:</strong>&nbsp;O‘qituvchining&nbsp;sanogen&nbsp;tafakkur&nbsp;subshkalari&nbsp;(refleksivlik,&nbsp;kognitiv&nbsp;moslashuvchanlik,&nbsp;emotsional&nbsp;regulyatsiya&nbsp;va&nbsp;boshqalar)&nbsp;bo‘yicha&nbsp;o‘sish&nbsp;ko‘rsatkichlarini&nbsp;real&nbsp;vaqt&nbsp;rejimida&nbsp;vizual&nbsp;grafiklarda&nbsp;aks&nbsp;ettiradi.</li><li><strong>Interaktiv&nbsp;biologik&nbsp;simulyatorlar&nbsp;va&nbsp;3D&nbsp;modellar&nbsp;bazasi:</strong>&nbsp;Murakkab&nbsp;biologik&nbsp;jarayonlarni&nbsp;(hujayra&nbsp;biologiyasi,&nbsp;genetika,&nbsp;fiziologiya)&nbsp;namoyish&nbsp;etishda&nbsp;vujudga&nbsp;keladigan&nbsp;texnik&nbsp;va&nbsp;metodik&nbsp;muammolarni&nbsp;bartaraf&nbsp;etuvchi&nbsp;tayyor&nbsp;didaktik&nbsp;manbalar&nbsp;majmuasi.</li><li><strong>Kognitiv&nbsp;korreksiya&nbsp;modullari:</strong>&nbsp;O‘qituvchining&nbsp;darsdagi&nbsp;emotsional&nbsp;zo‘riqishini&nbsp;pasaytiruvchi,&nbsp;salbiy&nbsp;fikrlarni&nbsp;ongli&nbsp;qayta&nbsp;baholashga&nbsp;yordam&nbsp;beruvchi&nbsp;interaktiv&nbsp;mashqlar&nbsp;va&nbsp;ssenariylar.</li></ul><h2>2.&nbsp;Sun’iy&nbsp;intellekt&nbsp;va&nbsp;o‘yinlashtirish&nbsp;texnologiyalarining&nbsp;sanogen&nbsp;fikrlashdagi&nbsp;o‘rni</h2><p>&quot;SanoTafEdu&quot;&nbsp;platformasi&nbsp;tarkibiga&nbsp;integratsiyalangan&nbsp;<strong>sun’iy&nbsp;intellekt</strong>&nbsp;va&nbsp;<strong>o‘yinlashtirish&nbsp;(gamifikatsiya)</strong>&nbsp;elementlari&nbsp;o‘qituvchining&nbsp;o‘z-o‘zini&nbsp;rivojlantirish&nbsp;motivatsiyasini&nbsp;barqarorlashtiradi:</p><ol><li><strong>Sun’iy&nbsp;intellekt&nbsp;yordamida&nbsp;refleksiv&nbsp;tahlil:</strong><ul><li>O‘qituvchi&nbsp;darsda&nbsp;yuz&nbsp;bergan&nbsp;muammoli&nbsp;holatni&nbsp;kiritganda,&nbsp;sun’iy&nbsp;intellekt&nbsp;A-B-C&nbsp;kognitiv&nbsp;modeli&nbsp;asosida&nbsp;salbiy&nbsp;fikrni&nbsp;rivojlantiruvchi&nbsp;va&nbsp;sog‘lom&nbsp;(sanogen)&nbsp;ramkaga&nbsp;ko‘chirish&nbsp;bo‘yicha&nbsp;shaxsiy&nbsp;metodik&nbsp;tavsiyalar&nbsp;beradi.</li></ul></li><li><strong>O‘yinlashtirish&nbsp;orqali&nbsp;ruhiy&nbsp;barqarorlikni&nbsp;oshirish:</strong><ul><li>O‘qituvchilarning&nbsp;zaxira&nbsp;dars&nbsp;rejalarini&nbsp;tuzishi,&nbsp;refleksiv&nbsp;kundalik&nbsp;yuritishi&nbsp;va&nbsp;axborotni&nbsp;saralash&nbsp;amaliyotlarini&nbsp;bajarishi&nbsp;interaktiv&nbsp;bosqichlar&nbsp;hamda&nbsp;natijaviy&nbsp;rag‘batlar&nbsp;orqali&nbsp;baholab&nbsp;boriladi.</li></ul></li></ol><pre data-language=\"plain\">\n┌────────────────────────────────────────────────────────────────────────┐\n│             &quot;SANOTAFEDU&quot; PLATFORMASINING STRUKTURAVIY MODELI           │\n└───────────────────────────────────┬────────────────────────────────────┘\n                                    │\n ┌──────────────────────────────────┴──────────────────────────────────┐\n │ 1. Tashxis va Shaxsiy Boshqaruv Paneli (Natijalar monitoringi)      │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 2. Sun’iy Intellekt Moduli (Refleksiv tahlil va qayta baholash)      │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 3. Biologik Metodik Bank (3D modellar, Virtual laboratoriyalar)     │\n ├─────────────────────────────────────────────────────────────────────┤\n │ 4. O‘yinlashtirilgan Rivojlanish Trayektoriyasi (Bosqichli o‘sish)   │\n └─────────────────────────────────────────────────────────────────────┘\n</pre><h2>3.&nbsp;Biologiya&nbsp;o‘qituvchisining&nbsp;uzluksiz&nbsp;o‘z-o‘zini&nbsp;takomillashtirish&nbsp;modeli</h2><p>Sanogen&nbsp;tafakkur&nbsp;—&nbsp;bu&nbsp;bir&nbsp;marta&nbsp;shakllantiriladigan&nbsp;ko‘nikma&nbsp;emas,&nbsp;balki&nbsp;<strong>uzluksiz&nbsp;o‘z-o‘zini&nbsp;takomillashtirib&nbsp;boruvchi&nbsp;hayotiy-kasbiy&nbsp;uslubdir</strong>.&nbsp;O‘qituvchi&nbsp;quyidagi&nbsp;bosqichlar&nbsp;orqali&nbsp;o‘z&nbsp;faoliyatini&nbsp;muntazam&nbsp;rivojlantirib&nbsp;boradi:</p><ul><li><strong>Iskalash&nbsp;va&nbsp;aniqlash&nbsp;bosqichi:</strong>&nbsp;&quot;SanoTafEdu&quot;&nbsp;platformasidagi&nbsp;tashxis&nbsp;vositalari&nbsp;orqali&nbsp;kognitiv&nbsp;zaifliklarni&nbsp;aniqlash.</li><li><strong>Modellashtirish&nbsp;va&nbsp;zaxiralash&nbsp;bosqichi:</strong>&nbsp;Raqamli&nbsp;biologiya&nbsp;darslari&nbsp;uchun&nbsp;muqobil&nbsp;(zaxira)&nbsp;ssenariylarni&nbsp;boyitib&nbsp;borish.</li><li><strong>Tarmoqli&nbsp;hamkorlik&nbsp;va&nbsp;tajriba&nbsp;almashish:</strong>&nbsp;Platformadagi&nbsp;kasbiy&nbsp;hamjamiyat&nbsp;orqali&nbsp;boshqa&nbsp;biologiya&nbsp;o‘qituvchilari&nbsp;bilan&nbsp;sanogen&nbsp;metodik&nbsp;yechimlarni&nbsp;ulashish.</li></ul><h2>4.&nbsp;Raqamli&nbsp;ta’lim&nbsp;muhitida&nbsp;sanogen&nbsp;muhitni&nbsp;yaratish&nbsp;va&nbsp;kutilayotgan&nbsp;natijalar</h2><p>O‘qituvchida&nbsp;sanogen&nbsp;tafakkurning&nbsp;rivojlanishi&nbsp;bevosita&nbsp;<strong>o‘quvchilarda&nbsp;ham&nbsp;sanogen&nbsp;ta’lim&nbsp;muhitining</strong>&nbsp;qaror&nbsp;topishiga&nbsp;olib&nbsp;keladi:</p><ol><li><strong>O‘quvchilar&nbsp;xavotirligining&nbsp;pasayishi:</strong>&nbsp;O‘qituvchining&nbsp;emotsional&nbsp;xotirjamligi&nbsp;va&nbsp;moslashuvchanligi&nbsp;darsda&nbsp;xavfsiz&nbsp;hamda&nbsp;ijodkorona&nbsp;ta’lim&nbsp;muhitini&nbsp;yaratadi.</li><li><strong>Kognitiv&nbsp;chidamlilik:</strong>&nbsp;Biologik&nbsp;bilimlarni&nbsp;o‘zlashtirishda&nbsp;o‘quvchilar&nbsp;xatolardan&nbsp;qo‘rqmasdan,&nbsp;ularni&nbsp;manba&nbsp;va&nbsp;tajriba&nbsp;deb&nbsp;bilishga&nbsp;o‘rganadilar.</li><li><strong>Kasbiy&nbsp;va&nbsp;o‘quv&nbsp;muvaffaqiyati:</strong>&nbsp;O‘qituvchi&nbsp;va&nbsp;o‘quvchining&nbsp;birgalikdagi&nbsp;sanogen&nbsp;o‘zaro&nbsp;ta’siri&nbsp;ta’lim&nbsp;unumdorligini&nbsp;hamda&nbsp;biologik&nbsp;ta’lim&nbsp;sifatini&nbsp;yangi&nbsp;bosqichga&nbsp;ko‘taradi.</li></ol><h3>Ma’ruza&nbsp;bo‘yicha&nbsp;xulosa</h3><p>&quot;SanoTafEdu&quot;&nbsp;raqamli&nbsp;platformasi,&nbsp;sun’iy&nbsp;intellekt&nbsp;va&nbsp;o‘yinlashtirish&nbsp;texnologiyalari&nbsp;biologiya&nbsp;o‘qituvchisiga&nbsp;raqamli&nbsp;ta’lim&nbsp;muhitida&nbsp;uzluksiz&nbsp;o‘z-o‘zini&nbsp;rivojlantirish&nbsp;imkoniyatini&nbsp;beradi.&nbsp;Ushbu&nbsp;tizimli&nbsp;yondashuv&nbsp;o‘qituvchining&nbsp;kasbiy&nbsp;yonib&nbsp;bitishining&nbsp;oldini&nbsp;olib,&nbsp;uning&nbsp;ruhiy&nbsp;salomatligi&nbsp;hamda&nbsp;pedagogik&nbsp;mahoratini&nbsp;oshirishga&nbsp;xizmat&nbsp;qiladi.</p>', '', '/storage/presentations/1784932666_7-Modul___SanoTafEdu__Raqamli_Platformasi_Integratsiyasi.pptx', 7, '2026-07-24 17:29:04', '2026-07-24 17:37:46'),
(16, 4, 'BIOLOGIYA O‘QITUVCHILARIDA SANOGEN TAFAKKURNI RIVOJLANTIRISHDA INTERAKTIV MAHORAT DARSLARI, KASBIY HAMJAMIYATLAR VA METODIK DASTUR INTEGRATSIYASI', '<h1>BIOLOGIYA&nbsp;O‘QITUVCHILARIDA&nbsp;SANOGEN&nbsp;TAFAKKURNI&nbsp;RIVOJLANTIRISHDA&nbsp;INTERAKTIV&nbsp;MAHORAT&nbsp;DARSLARI,&nbsp;KASBIY&nbsp;HAMJAMIYATLAR&nbsp;VA&nbsp;METODIK&nbsp;DASTUR&nbsp;INTEGRATSIYASI</h1><p><strong>O‘quv&nbsp;soati:</strong>&nbsp;4&nbsp;soat&nbsp;(1&nbsp;soat&nbsp;ma’ruza,&nbsp;1&nbsp;soat&nbsp;amaliy,&nbsp;2&nbsp;soat&nbsp;mustaqil&nbsp;ish)</p><p><strong>Maqsadi:</strong>&nbsp;Biologiya&nbsp;o‘qituvchilarida&nbsp;interaktiv&nbsp;mahorat&nbsp;darslari,&nbsp;kasbiy&nbsp;hamjamiyatlar&nbsp;hamda&nbsp;hamkorlikda&nbsp;darsni&nbsp;tahlil&nbsp;qilish&nbsp;vositalari&nbsp;orqali&nbsp;sanogen&nbsp;tafakkurni&nbsp;kollegial&nbsp;rivojlantirish&nbsp;va&nbsp;metodik&nbsp;ta’minotni&nbsp;amaliyotga&nbsp;tatbiq&nbsp;etish&nbsp;ko‘nikmalarini&nbsp;shakllantirish.</p><h2>1.&nbsp;Interaktiv&nbsp;mahorat&nbsp;darslari&nbsp;va&nbsp;tajriba&nbsp;almashish&nbsp;usullari</h2><p>Biologiya&nbsp;o‘qituvchilarining&nbsp;sanogen&nbsp;tafakkurini&nbsp;rivojlantirishda&nbsp;yakkalangan&nbsp;holda&nbsp;ishlash&nbsp;yetarli&nbsp;emas.&nbsp;<strong>Interaktiv&nbsp;mahorat&nbsp;darslari</strong>&nbsp;o‘qituvchilarning&nbsp;o‘zaro&nbsp;tajriba&nbsp;almashishi&nbsp;hamda&nbsp;kognitiv&nbsp;qiyinchiliklarni&nbsp;birgalikda&nbsp;yengishi&nbsp;uchun&nbsp;qulay&nbsp;pedagogik&nbsp;muhit&nbsp;hisoblanadi:</p><ol><li><strong>Muammoli&nbsp;ssenariylarni&nbsp;simulyatsiya&nbsp;qilish:</strong>&nbsp;Dars&nbsp;jarayonida&nbsp;yuzaga&nbsp;keladigan&nbsp;kutilmagan&nbsp;texnik&nbsp;nosozliklar&nbsp;va&nbsp;pedagogik&nbsp;ziddiyatlarni&nbsp;mahorat&nbsp;darsida&nbsp;sun’iy&nbsp;hosil&nbsp;qilib,&nbsp;ularni&nbsp;sanogen&nbsp;refleksiya&nbsp;orqali&nbsp;ijobiy&nbsp;hal&nbsp;etish&nbsp;usullari&nbsp;namoyish&nbsp;etiladi.</li><li><strong>Jonli&nbsp;dars&nbsp;va&nbsp;zaxira&nbsp;rejalar&nbsp;namoyishi:</strong>&nbsp;Tajribali&nbsp;o‘qituvchilar&nbsp;raqamli&nbsp;va&nbsp;3D&nbsp;vositalardan&nbsp;foydalanish&nbsp;bilan&nbsp;birga,&nbsp;kutilmagan&nbsp;vaziyatda&nbsp;zudlik&nbsp;bilan&nbsp;zaxira&nbsp;rejasiga&nbsp;(Plan&nbsp;B)&nbsp;o‘tish&nbsp;mahoratini&nbsp;amalda&nbsp;ko‘rsatadilar.</li></ol><h2>2.&nbsp;Kasbiy&nbsp;hamjamiyatlar&nbsp;va&nbsp;ustoz-shogirdlik&nbsp;an’anasida&nbsp;sanogen&nbsp;yondashuv</h2><p>O‘qituvchilarning&nbsp;kasbiy&nbsp;hamjamiyatlarda&nbsp;(<em>metodik&nbsp;birlashmalar,&nbsp;tuman&nbsp;va&nbsp;viloyat&nbsp;biologlar&nbsp;hamjamiyati</em>)&nbsp;birlashishi&nbsp;ularning&nbsp;psixologik&nbsp;va&nbsp;metodik&nbsp;barqarorligini&nbsp;ta’minlaydi:</p><ul><li><strong>Tengdosh&nbsp;ustozligi&nbsp;hamda&nbsp;ko‘mak:</strong>&nbsp;Tajribali&nbsp;biologiya&nbsp;o‘qituvchisi&nbsp;yosh&nbsp;hamkasbiga&nbsp;faqat&nbsp;fanni&nbsp;o‘qitish&nbsp;metodikasini&nbsp;emas,&nbsp;balki&nbsp;darsdagi&nbsp;emotsional&nbsp;zo‘riqishlarni&nbsp;yengish&nbsp;hamda&nbsp;sanogen&nbsp;fikrlash&nbsp;usullarini&nbsp;ham&nbsp;o‘rgatadi.</li><li><strong>Qo‘llab-quvvatlovchi&nbsp;va&nbsp;tanqidsiz&nbsp;muloqot:</strong>&nbsp;Kasbiy&nbsp;hamjamiyatda&nbsp;hamkasbning&nbsp;darsdagi&nbsp;xatosini&nbsp;ayblash&nbsp;emas,&nbsp;balki&nbsp;uni&nbsp;o‘quv&nbsp;va&nbsp;metodik&nbsp;tajriba&nbsp;sifatida&nbsp;xolis&nbsp;tahlil&nbsp;qilish&nbsp;ko‘nikmasi&nbsp;qaror&nbsp;topadi.</li></ul><h2>3.&nbsp;Darsni&nbsp;birgalikda&nbsp;tahlil&nbsp;qilish&nbsp;(Lesson&nbsp;Study)&nbsp;va&nbsp;sanogen&nbsp;refleksiya</h2><p>Dars&nbsp;kuzatuvi&nbsp;va&nbsp;tahlili&nbsp;o‘qituvchi&nbsp;uchun&nbsp;stress&nbsp;manbai&nbsp;bo‘lmasligi,&nbsp;aksincha,&nbsp;kasbiy&nbsp;o‘sish&nbsp;omiliga&nbsp;aylanishi&nbsp;lozim:</p><ol><li><strong>Birgalikda&nbsp;rejalashtirish:</strong>&nbsp;Kasbiy&nbsp;hamjamiyat&nbsp;a’zolari&nbsp;biologiya&nbsp;darsining&nbsp;o‘quv&nbsp;maqsadi&nbsp;va&nbsp;zaxira&nbsp;rejalarini&nbsp;birgalikda&nbsp;loyihalashtiradilar.</li><li><strong>O‘qituvchi&nbsp;shaxsini&nbsp;emas,&nbsp;metodni&nbsp;tahlil&nbsp;qilish:</strong>&nbsp;Dars&nbsp;kuzatuvidan&nbsp;so‘ng&nbsp;o‘qituvchi&nbsp;shaxsiga&nbsp;baho&nbsp;berish&nbsp;taqiqlanadi.&nbsp;Diqqat-e’tibor&nbsp;faqat&nbsp;qo‘llanilgan&nbsp;vositalar,&nbsp;o‘quvchilarning&nbsp;kognitiv&nbsp;reaksiyalari&nbsp;hamda&nbsp;o‘qituvchining&nbsp;emotsional&nbsp;xotirjamligiga&nbsp;qaratiladi.</li></ol><h2>4.&nbsp;Maktab&nbsp;va&nbsp;tuman&nbsp;miqyosida&nbsp;sanogen&nbsp;metodik&nbsp;tizimni&nbsp;ommalashtirish</h2><p>Sanogen&nbsp;tafakkurni&nbsp;rivojlantirish&nbsp;dasturi&nbsp;maktab,&nbsp;tuman&nbsp;va&nbsp;viloyat&nbsp;darajasida&nbsp;tizimli&nbsp;ravishda&nbsp;yo‘lga&nbsp;qo‘yiladi:</p><ul><li><strong>Zaxira&nbsp;dars&nbsp;ishlanmalari&nbsp;bankini&nbsp;boyitish:</strong>&nbsp;Biologiya&nbsp;fani&nbsp;bo‘yicha&nbsp;eng&nbsp;murakkab&nbsp;va&nbsp;raqamlashtirilgan&nbsp;konsepsiyalar&nbsp;uchun&nbsp;muqobil&nbsp;dars&nbsp;rejalari&nbsp;bazasini&nbsp;yaratish&nbsp;va&nbsp;ochiq&nbsp;foydalanishga&nbsp;topshirish.</li><li><strong>Muntazam&nbsp;refleksiv&nbsp;uchrashuvlar:</strong>&nbsp;Har&nbsp;oyda&nbsp;1&nbsp;marotaba&nbsp;biologiya&nbsp;o‘qituvchilarining&nbsp;kasbiy&nbsp;ruhiy&nbsp;salomatligi&nbsp;hamda&nbsp;pedagogik&nbsp;muvaffaqiyatlariga&nbsp;bag‘ishlangan&nbsp;uchrashuvlarni&nbsp;o‘tkazish.</li></ul><h3>8&nbsp;Ma’ruza&nbsp;bo‘yicha&nbsp;xulosa</h3><p>Mahorat&nbsp;darslari,&nbsp;kasbiy&nbsp;hamjamiyatlar&nbsp;va&nbsp;hamkorlikda&nbsp;darsni&nbsp;tahlil&nbsp;qilish&nbsp;usullari&nbsp;biologiya&nbsp;o‘qituvchilarida&nbsp;sanogen&nbsp;tafakkurni&nbsp;uzluksiz&nbsp;rivojlantirishning&nbsp;amaliy&nbsp;harakatlantiruvchi&nbsp;kuchidir.&nbsp;Kollegial&nbsp;qo‘llab-quvvatlash&nbsp;va&nbsp;o‘zaro&nbsp;tajriba&nbsp;almashish&nbsp;o‘qituvchini&nbsp;kasbiy&nbsp;yakkalanib&nbsp;qolishdan&nbsp;hamda&nbsp;ruhiy&nbsp;charchashdan&nbsp;asrab,&nbsp;ta’lim&nbsp;sifatini&nbsp;oshiradi.</p>', '', '/storage/presentations/1784933249_8-Modul__Biologiya_O_qituvchilarida_Sanogen_Tafakkurni_Rivojlantirishda_Mahorat_Darslari_va_Kasbiy_Hamjamiyatlar.pptx', 8, '2026-07-24 17:41:14', '2026-07-24 17:47:29');
