INSERT INTO `questions` (`id`, `module_id`, `question_text`, `options`, `created_at`, `updated_at`, `type`, `ai_rubric`, `video_timestamp`) VALUES
(15, 9, '\"Sanogen tafakkur\" tushunchasi ilmiy muomalaga kim tomonidan olib kirilgan va uning asosiy mohiyati nimadan iborat?', '[{\"text\":\"D. Schon \\u2014 harakatdagi refleksiya va metakognitiv nazorat\",\"is_correct\":false},{\"text\":\"Yu.M. Orlov \\u2014 shaxsning o\\u02bbz emotsional holati va fikrlash naqshlarini ongli ravishda tartibga solishi\",\"is_correct\":true},{\"text\":\"A. Beck \\u2014 kognitiv xatolar va avtomatik fikrlarni terapiya qilish\",\"is_correct\":false},{\"text\":\"D. Kolb \\u2014 tajribaviy o\\u02bbrganish va amaliy ko\\u02bbnikmalarni shakllantirish\",\"is_correct\":false}]', '2026-07-24 14:55:32', '2026-07-24 14:55:32', 'multiple_choice', NULL, NULL),
(16, 9, 'Pedagogik faoliyatda uchraydigan \"Patogen tafakkur\"ga xos boʻlgan asosiy xususiyatni aniqlang:', '[{\"text\":\"Qiyin pedagogik vaziyatda muammoning yechimini izlash va amaliy harakat qilish\",\"is_correct\":false},{\"text\":\"Salbiy emotsional kechinmalar, xavotir hamda xatolarni miyada anglanmagan holda qayta-qayta aylantirish\",\"is_correct\":true},{\"text\":\"Dars jarayonidagi texnik nosozliklarni xotirjam va zaxira reja orqali hal etish\",\"is_correct\":false},{\"text\":\"Hamkasblarining muvaffaqiyatidan kasbiy tajriba va o\\u02bbrganish imkoniyatini izlash\",\"is_correct\":false}]', '2026-07-24 14:56:25', '2026-07-24 14:56:25', 'multiple_choice', NULL, NULL),
(17, 9, 'Biologiya oʻqituvchisida raqamli taʼlim muhitida \"Sanogen reaksiya\" namoyon boʻlishining toʻgʻri koʻrinishi qaysi javobda berilgan?', '[{\"text\":\"Raqamli platformalardan foydalanishda \\\"men zamondan orqada qolyapman\\\" deb o\\u02bbzini ayblash\",\"is_correct\":false},{\"text\":\"Virtual laboratoriya yoki 3D texnologiyalar ishlamay qolganda darsni zudlik bilan to\\u02bbxtatish\",\"is_correct\":false},{\"text\":\"Raqamli vositalarni o\\u02bbz imkoniyatlarini kengaytiruvchi didaktik ko\\u02bbmakchi sifatida ko\\u02bbrib, texnik murakkabliklarni bosqichma-bosqich o\\u02bbzlashtirish\",\"is_correct\":true},{\"text\":\"Darsda doim bir xil an\\u02bcanaviy metodlarni qo\\u02bbllashni ma\\u02bcqul ko\\u02bbrib, yangi platformalarni o\\u02bbrganishdan qochish\",\"is_correct\":false}]', '2026-07-24 14:57:04', '2026-07-24 14:57:04', 'multiple_choice', NULL, NULL),
(18, 9, 'Sanogen tafakkur kompetensiyasining 5 ta asosiy subshkalasiga quyidagilardan qaysilar kiradi?', '[{\"text\":\"Refleksivlik, Kognitiv moslashuvchanlik, Emotsional regulyatsiya, Konstruktiv faollik, Axborot selektivligi\",\"is_correct\":true},{\"text\":\"Nazariy bilim, Amaliy ko\\u02bbnikma, Texnik savodxonlik, Dars rejalashtirish, Metodik tayyorgarlik\",\"is_correct\":false},{\"text\":\"Tashqi motivatsiya, Psixologik travma, Kognitiv dissonans, Fojialashtirish, Emotsional yonib bitish\",\"is_correct\":false},{\"text\":\"Shaxsiy intizom, Raqamli xavfsizlik, Pedagogik takt, Nutq madaniyati, Hamkorlikda ishlash\",\"is_correct\":false}]', '2026-07-24 14:57:50', '2026-07-24 14:57:50', 'multiple_choice', NULL, NULL),
(19, 9, 'Sanogen refleksiya algoritmining toʻgʻri ketma-ketligini belgilang:', '[{\"text\":\"Harakat va tinchlanish $\\\\rightarrow$ Emotsiyani anglash $\\\\rightarrow$ Kognitiv xatoni ajratish $\\\\rightarrow$ Refreyming\",\"is_correct\":false},{\"text\":\"Kognitiv xatoni ajratish $\\\\rightarrow$ Harakat va tinchlanish $\\\\rightarrow$ Emotsiyani anglash $\\\\rightarrow$ Refreyming\",\"is_correct\":false},{\"text\":\"Emotsiyani anglash va nomlash $\\\\rightarrow$ Kognitiv xatoni ajratib olish $\\\\rightarrow$ Konstruktiv refreyming (qayta baholash) $\\\\rightarrow$ Harakat va tinchlanish\",\"is_correct\":true},{\"text\":\"Refreyming $\\\\rightarrow$ Emotsiyani anglash $\\\\rightarrow$ Harakat va tinchlanish $\\\\rightarrow$ Kognitiv xatoni ajratib olish\",\"is_correct\":false}]', '2026-07-24 14:58:32', '2026-07-24 14:58:32', 'multiple_choice', NULL, NULL),
(20, 9, 'Sanogen va patogen tafakkur tushunchalarining maʼnosi nimada? Yu.M. Orlov nazariyasiga koʻra ularning asosiy farqlari va oʻqituvchi ruhiyatiga taʼsirini tushuntirib bering.', '[]', '2026-07-24 15:02:14', '2026-07-24 15:02:14', 'open_ended', 'Kalit tushunchalar: Yu.M. Orlov, sano (sogʻlomlashtirish), patogen (kasallik keltirib chiqaruvchi), emotsional regulyatsiya, rumination (fikrlarni aylantirish), kasbiy yonib bitish.', NULL),
(21, 9, 'Patogen tafakkurga xos boʻlgan kognitiv xatolar (rumination, fojialashtirish) oʻqituvchi faoliyatida qanday oqibatlarga olib keladi? Kasbiy yonib bitish (burnout syndrome) va ruhiy charchoq nuqtai nazaridan asoslang.', '[]', '2026-07-24 15:03:58', '2026-07-24 15:03:58', 'open_ended', 'Kalit tushunchalar: Rumination, fojialashtirish (catastrophizing), kognitiv xatolar, kasbiy yonib bitish (burnout), emotsional zoʻriqish, motivatsiya yoʻqolishi.', NULL),
(22, 9, 'Raqamli taʼlim muhitida (3D modellar, virtual laboratoriyalar, platformalar bilan ishlashda) biologiya oʻqituvchisida sanogen va patogen reaksiyalar qanday namoyon boʻladi? Amaliy misollar bilan qiyoslang.', '[]', '2026-07-24 15:04:26', '2026-07-24 15:04:26', 'open_ended', 'Kalit tushunchalar: Texnofobiya, raqamli toʻsiq, kognitiv moslashuvchanlik, zaxira reja (Plan B), didaktik koʻmakchi.', NULL),
(23, 9, 'Sanogen tafakkur kompetensiyasining 5 ta asosiy subshkalasini (Refleksivlik, Kognitiv moslashuvchanlik, Emotsional regulyatsiya, Konstruktiv faollik, Axborot selektivligi) qisqacha tavsiflab bering.', '[]', '2026-07-24 15:05:14', '2026-07-24 15:05:14', 'open_ended', 'Kalit tushunchalar: Refleksivlik, Kognitiv moslashuvchanlik, Emotsional regulyatsiya, Konstruktiv faollik, Axborot selektivligi.', NULL),
(24, 9, 'Sanogen refleksiya algoritmining 4 ta bosqichini (Emotsional reaksiyani anglash $\\rightarrow$ Kognitiv xatoni ajratish $\\rightarrow$ Refreyming $\\rightarrow$ Harakat va tinchlanish) biologiya darsidagi real pedagogik vaziyat misolida tushuntiring.', '[]', '2026-07-24 15:05:38', '2026-07-24 15:05:38', 'open_ended', 'AI uchun kalit tushunchalar: Emotsiyani anglash, Kognitiv xato, Refreyming (qayta baholash), Harakat va tinchlanish.', NULL),
(25, 10, 'Patogen tafakkurning pedagogik faoliyatda uchraydigan asosiy turlarini (xavotirlik, fojialashtirish, aybdorlik va xafagarchilik) va ularning kognitiv ildizlarini tushuntirib bering.', '[]', '2026-07-24 15:33:02', '2026-07-24 15:33:02', 'open_ended', 'Kalit tushunchalar: Xavotirlik, texnofobiya, fojialashtirish (catastrophizing), \"yoki hamma narsa, yoki hech narsa\" tamoyili, aybdorlik hissi, xafagarchilik, rumination.', NULL),
(26, 10, 'Kognitiv-xulq-atvor psixologiyasidagi ABC modelining tarkibiy qismlarini (A, B, C) biologiya oʻqituvchisining raqamli taʼlim muhitidagi amaliy faoliyati misolida tushuntiring.', '[]', '2026-07-24 15:33:29', '2026-07-24 15:33:29', 'open_ended', 'Kalit tushunchalar: A (Activating Event — voqea), B (Beliefs — fikr/eʼtiqod), C (Consequences — emotsiya/oqibat), ABC modeli, kognitiv talqin', NULL),
(27, 10, 'Nima uchun ABC modelida inson emotsiyasi va xulq-atvorini voqeaning oʻzi (A) emas, balki voqea haqidagi fikrlar (B) belgilaydi deb hisoblanadi? Ilmiy va psixologik jihatdan asoslang.', '[]', '2026-07-24 15:33:51', '2026-07-24 15:33:51', 'open_ended', 'Kalit tushunchalar: Kognitiv qayta ishlash, idrok etish (perception), shaxsiy eʼtiqodlar, subyektiv talqin, kognitiv filtri', NULL),
(28, 10, 'Refreyming (kognitiv qayta tuzilish) texnikasining mohiyati va uni oʻtkazishning 3 ta asosiy bosqichini tushuntirib bering.', '[]', '2026-07-24 15:34:16', '2026-07-24 15:34:16', 'open_ended', 'Kalit tushunchalar: Refreyming, kognitiv ramka (frame), patogen ramka, dalillarni tekshirish, sanogen ramka (qayta baholash).', NULL),
(29, 10, 'Quyidagi patogen fikrga sanogen refreyming berib, uni konstruktiv fikrga oʻtkazing: \"Oʻquvchilar 3D modeldagi hujayra tuzilishini tushunishmadi, demak men zamonaviy interaktiv metodlarni qoʻllay olmaydigan yomon oʻqituvchiman.\"', '[]', '2026-07-24 15:34:36', '2026-07-24 15:34:36', 'open_ended', 'Kalit tushunchalar: Shaxsiylashtirishni yoʻqotish, rivojlanish imkoniyati, metodikani soddalashtirish, vaqt omili, sanogen qayta baholash', NULL),
(30, 10, 'Patogen tafakkur turlaridan biri boʻlgan \"Fojialashtirish\" holatining asosiy sababi va ildizi nimadan iborat?', '[{\"text\":\"Shaxsiy mas\\u02bculiyat me\\u02bcyorlarining buzilishi va har bir narsani o\\u02bbz zimmasiga oshiqcha olish\",\"is_correct\":false},{\"text\":\"Cheklangan va qat\\u02bciy fikrlash hamda \\\"yoki hamma narsa, yoki hech narsa\\\" qoidasiga tayanish\",\"is_correct\":true},{\"text\":\"Boshqalarga nisbatan haqiqatga mos kelmaydigan o\\u02bbta yuqori talablar qo\\u02bbyish\",\"is_correct\":false},{\"text\":\"Raqamli axborotlarni saralashdagi aqliy charchoq va toboralash\",\"is_correct\":false}]', '2026-07-24 15:37:13', '2026-07-24 15:37:13', 'multiple_choice', NULL, NULL),
(31, 10, 'Ruhiyatda qoʻllaniladigan A-B-C (Voqea — Fikr — Oqibat) mantiqiy zanjirida \"B\" (Fikr va eʼtiqod) bosqichi nimani anglatadi?', '[{\"text\":\"Tashqi muhitda kutilmaganda yuz bergan hodisa yoki vaziyatni\",\"is_correct\":false},{\"text\":\"Fikr natijasida kelib chiqadigan his-tuyg\\u02bbu va xatti-harakatlarni\",\"is_correct\":false},{\"text\":\"Yuz bergan voqeaga nisbatan insonning ichki qarashi, fikri va unga bergan bahosini\",\"is_correct\":true},{\"text\":\"Dars jarayonida uchragan texnik uzilishlarni bartaraf etish rejasini\",\"is_correct\":false}]', '2026-07-24 15:37:53', '2026-07-24 15:37:53', 'multiple_choice', NULL, NULL),
(32, 10, 'Biologiya darsida koʻrgazmali raqamli dastur ishlamay qolganda oʻqituvchida yuzaga keladigan quyidagi holatlardan qaysi biri \"Sanogen (sogʻlom) oqibat\" hisoblanadi?', '[{\"text\":\"Darsni zudlik bilan to\\u02bbxtatib, o\\u02bbzini va jihozlarni ayblash\",\"is_correct\":false},{\"text\":\"Vahimaga tushib, sinfdagi o\\u02bbquvchilarga asabiylashish\",\"is_correct\":false},{\"text\":\"Xotirjamlikni saqlab, doskada mavzuni tushuntirishga va savol-javobga o\\u02bbtish\",\"is_correct\":true},{\"text\":\"Dars o\\u02bbtishdan ko\\u02bbngli qolib, mashg\\u02bbulot rejasini bekor qilish\",\"is_correct\":false}]', '2026-07-24 15:38:26', '2026-07-24 15:38:26', 'multiple_choice', NULL, NULL),
(33, 10, 'Salbiy yoki zararli vaziyatga berilgan maʼnoni oʻzgartirib, uni ijobiy hamda rivojlantiruvchi shaklda qayta baholash usuli nima deyiladi?', '[{\"text\":\"Surunkali o\\u02bbyga tolish (xayolda qayta-qayta aylantirish)\",\"is_correct\":false},{\"text\":\"Qayta baholash usuli (Fikrni sanogen shaklga o\\u02bbtkazish)\",\"is_correct\":true},{\"text\":\"Vaziyatdan chekinish (uzoqda turib kuzatish)\",\"is_correct\":false},{\"text\":\"Beparvolik va mas\\u02bculiyatsizlik\",\"is_correct\":false}]', '2026-07-24 15:39:02', '2026-07-24 15:39:02', 'multiple_choice', NULL, NULL),
(34, 10, '\"Oʻquvchilar modeldagi hujayra tuzilishini tushunishmadi, demak men dars oʻta olmaydigan yomon oʻqituvchiman\" degan zararli fikrga berilgan toʻgʻri va sogʻlom qayta baholashni aniqlang:', '[{\"text\":\"\\\"Hujayra tuzilishi murakkab, o\\u02bbquvchilar tushunmagan bo\\u02bblsa, bu fanni o\\u02bbqitish umuman samarasiz.\\\"\",\"is_correct\":false},{\"text\":\"\\\"Yangi vositalarni o\\u02bbzlashtirish vaqt talab etadi. Bu mening yomonligim emas, tushuntirish usulimni soddalashtirish uchun imkoniyat.\\\"\",\"is_correct\":true},{\"text\":\"\\\"O\\u02bbquvchilar e\\u02bctiborsiz bo\\u02bblgani uchun tushunishmadi, ayb faqat ularning o\\u02bbzida.\\\"\",\"is_correct\":false},{\"text\":\"\\\"Bundan keyin darslarimda raqamli va ko\\u02bbrgazmali vositalardan umuman foydalanmayman.\\\"\",\"is_correct\":false}]', '2026-07-24 15:39:48', '2026-07-24 15:39:48', 'multiple_choice', NULL, NULL),
(35, 11, 'Raqamli taʼlim muhitida oʻqituvchining texnikadan va yangilikdan qoʻrqish hamda surunkali xavotirlik darajasini pasaytirish uchun 3D vosita va simulyatsiyalarni darsga kichik qismlar holida (3-5 daqiqa) bosqichma-bosqich kiritib borish usuli nima deyiladi?', '[{\"text\":\"Surunkali o\\u02bbyga tolish\",\"is_correct\":false},{\"text\":\"Bosqichma-bosqich moslashish usuli\",\"is_correct\":true},{\"text\":\"Fojialashtirish va bo\\u02bbrttirish\",\"is_correct\":false},{\"text\":\"Beparvolik hamda mas\\u02bculiyatsizlik\",\"is_correct\":false}]', '2026-07-24 15:57:50', '2026-07-24 15:57:50', 'multiple_choice', NULL, NULL),
(36, 11, 'Raqamli biologiya darsida koʻrgazmali dastur yoki virtual laboratoriya ishlamay qolganda, amaliy fikrlash jarayonida eng birinchi qilinishi kerak boʻlgan kognitiv harakat qaysi?', '[{\"text\":\"Dars o\\u02bbtkazish rejasini butunlay bekor qilish\",\"is_correct\":false},{\"text\":\"Aybdorni qidirish va o\\u02bbz-o\\u02bbziga emotsional salbiy baho berish\",\"is_correct\":false},{\"text\":\"Yuz bergan holatni fojia emas, balki darsning tabiiy texnik qismi sifatida xolis qabul qilish\",\"is_correct\":true},{\"text\":\"O\\u02bbquvchilarga raqamli texnologiyalar bilan ishlash samarasiz ekanligini aytish\",\"is_correct\":false}]', '2026-07-24 15:58:40', '2026-07-24 15:58:40', 'multiple_choice', NULL, NULL),
(37, 11, 'Katta hajmdagi raqamli hamda biologik axborotlar oqimida oʻqituvchining aqliy charchashining (ortiqcha yuklama) oldini oluvchi va faqat kerakli resurslarni saralashga xizmat qiluvchi sanogen imkoniyat qaysi?', '[{\"text\":\"Fikrning elastikligi va moslashuvchanligi\",\"is_correct\":false},{\"text\":\"Axborotni tanlab saralash imkoniyati\",\"is_correct\":true},{\"text\":\"O\\u02bbz-o\\u02bbzini kuzatish va tahlil qilish\",\"is_correct\":false},{\"text\":\"Yaratuvchanlik faolligi\",\"is_correct\":false}]', '2026-07-24 15:59:22', '2026-07-24 15:59:22', 'multiple_choice', NULL, NULL),
(39, 11, 'Biologiya darsida raqamli texnologiyalarga nisbatan \"Qayta baholash usuli\" qoʻllanilganda, texnologiyaning darsdagi oʻrni va vazifasi qanday idrok etiladi?', '[{\"text\":\"Darsning asosiy va yagona maqsadi sifatida\",\"is_correct\":false},{\"text\":\"O\\u02bbqituvchi mahoratini pasaytiruvchi salbiy omil sifatida\",\"is_correct\":false},{\"text\":\"Biologik tushuncha va jarayonlarni anglashni osonlashtiruvchi ko\\u02bbrgazmali vosita sifatida\",\"is_correct\":true},{\"text\":\"Dars vaqtini sun\\u02bciy ravishda uzaytiruvchi ortiqcha yuklama sifatida\",\"is_correct\":false}]', '2026-07-24 16:00:47', '2026-07-24 16:00:47', 'multiple_choice', NULL, NULL),
(40, 11, 'Oʻqituvchida sanogen tafakkurni rivojlantirish uchun zarur boʻlgan va oʻz faoliyatidagi xatolardan qoʻrqmasdan, ularni ilmiy-metodik tahlil qilish imkonini beruvchi pedagogik shart-sharoit qaysi javobda koʻrsatilgan?', '[{\"text\":\"Fikrni tahlil qilish va baholash muhitini yaratish\",\"is_correct\":true},{\"text\":\"An\\u02bcanaviy dars metodlariga to\\u02bbliq qaytish\",\"is_correct\":false},{\"text\":\"Faqat tashqi rag\\u02bbbatlantirishga tayanib ishlash\",\"is_correct\":false},{\"text\":\"Raqamli vositalardan foydalanishni cheklash\",\"is_correct\":false}]', '2026-07-24 16:03:40', '2026-07-24 16:03:40', 'multiple_choice', NULL, NULL),
(41, 11, 'Raqamli taʼlim muhitida biologiya oʻqituvchilarida texnikadan qoʻrqish va xavotirlikni kamaytirishda \"Bosqichma-bosqich moslashish\" usulining mohiyati va ahamiyati nimadan iborat?', '[]', '2026-07-24 16:06:11', '2026-07-24 16:06:11', 'open_ended', 'Kalit tushunchalar: Bosqichma-bosqich moslashish, qisqa simulyatsiyalar, texnikadan qoʻrqishni kamaytirish, xavotirlikni pasaytirish, kognitiv yengillik.', NULL),
(42, 11, 'Virtual laboratoriyalar va uch oʻlchamli modellar bilan ishlashda kutilmagan texnik uzilish yuz berganda, oʻqituvchi qanday amaliy va sogʻlom fikrlash bosqichlarini amalga oshirishi kerak?', '[]', '2026-07-24 16:06:31', '2026-07-24 16:06:31', 'open_ended', 'Kalit tushunchalar: Xolis qabul qilish, aybdorlikni yoʻqotish, zaxira reja, muammoli savol-javob, amaliy xulosa chiqarish.', NULL),
(43, 11, 'Katta hajmdagi raqamli va biologik maʼlumotlar oqimida oʻqituvchini aqliy toboralash hamda charchashdan (ruhiy zoʻriqishdan) saqlovchi \"Axborotni tanlab saralash\" imkoniyati qanday namoyon boʻladi?', '[]', '2026-07-24 16:06:54', '2026-07-24 16:06:54', 'open_ended', 'Kalit tushunchalar: Axborotni tanlab saralash, aqliy charchash, axborot ortiqchaligi, saralash mezonlari, ruhiy salomatlik.', NULL),
(44, 11, 'Raqamli taʼlim muhitida biologiya oʻqituvchisining ruhiy zoʻriqishi va kasbiy yonib bitishining oldini olishda qanday metodik tadbirlar hamda mashqlar samarali hisoblanadi?', '[]', '2026-07-24 16:07:30', '2026-07-24 16:07:30', 'open_ended', 'Kalit tushunchalar: Kasbiy yonib bitish profilaktikasi, axborotni saralash, muvaffaqiyatlar kundaligi, oʻz-oʻzini kuzatish, ruhiy muvozanat.', NULL),
(45, 11, 'Oʻqituvchida sogʻlom va rivojlantiruvchi tafakkurni barqaror shakllantirish uchun zarur boʻlgan 3 ta asosiy pedagogik shart-sharoitni tushuntirib bering.', '[]', '2026-07-24 16:08:03', '2026-07-24 16:08:03', 'open_ended', 'Kalit tushunchalar: Fikrni tahlil qilish muhiti, raqamli-metodik yordam, oʻz-oʻzini boshqarish kuzatuvi.', NULL),
(46, 12, 'Raqamli taʼlim muhitida biologiya oʻqituvchilarining sanogen tafakkurini tashxis qilishning (aniqlashning) asosiy maqsadi nimadan iborat?', '[{\"text\":\"O\\u02bbqituvchilarning dars soatlarini kamaytirish yoki oshirish\",\"is_correct\":false},{\"text\":\"O\\u02bbqituvchining ruhiy holati, fikrlash usullari va kutilmagan vaziyatlarga reaksiyasini xolis o\\u02bbrganish hamda takomillashtirish\",\"is_correct\":true},{\"text\":\"An\\u02bcanaviy o\\u02bbqitish usullarini to\\u02bbliq taqiqlash\",\"is_correct\":false},{\"text\":\"O\\u02bbqituvchilarni faqat raqamli texnologiyalar bilan ishlashga majburlash\",\"is_correct\":false}]', '2026-07-24 16:27:15', '2026-07-24 16:27:15', 'multiple_choice', NULL, NULL),
(47, 12, 'Raqamli darsda kutilmagan texnik toʻsiq yuz berganda, oʻqituvchining asabiylashmasdan va vahimaga tushmasdan bir dars rejasidan ikkinchi (zaxira) rejasiga tezkor oʻta olish qobiliyati sanogen tafakkurning qaysi subshkalasiga (yoʻnalishiga) kiradi?', '[{\"text\":\"Refleksivlik (o\\u02bbz-o\\u02bbzini tahlil qilish)\",\"is_correct\":false},{\"text\":\"Axborotni tanlab saralash\",\"is_correct\":false},{\"text\":\"Kognitiv moslashuvchanlik (fikr elastikligi)\",\"is_correct\":true},{\"text\":\"Surunkali o\\u02bbyga tolish\",\"is_correct\":false}]', '2026-07-24 16:28:35', '2026-07-24 16:28:35', 'multiple_choice', NULL, NULL),
(48, 12, 'Dars jarayonida texnik nosozlik yoki murakkablik yuz berganda, oʻzini yoki boshqalarni ayblamasdan, darhol amaliy yechimga va zaxira rejasiga oʻtuvchi oʻqituvchi sanogen tafakkurning qaysi darajasida va sifatiga ega hisoblanadi?', '[{\"text\":\"Quyi daraja \\u2014 fojialashtiruvchi reaksiya\",\"is_correct\":false},{\"text\":\"Yuqori (barqaror-sanogen) daraja \\u2014 konstruktiv faollik\",\"is_correct\":false},{\"text\":\"O\\u02bbrta daraja \\u2014 surunkali xavotirlik\",\"is_correct\":true},{\"text\":\"Boshlang\\u02bbich daraja \\u2014 beparvolik\",\"is_correct\":false}]', '2026-07-24 16:29:45', '2026-07-24 16:29:45', 'multiple_choice', NULL, NULL),
(49, 12, 'Sanogen tafakkur darajasini baholashda oʻqituvchilar qaysi 3 ta asosiy darajaga ajratiladi?', '[{\"text\":\"A\\u02bclo, yaxshi, qoniqarsiz\",\"is_correct\":false},{\"text\":\"Nazariy, amaliy, metodik\",\"is_correct\":false},{\"text\":\"Boshlang\\u02bbich, o\\u02bbrta, oliy\",\"is_correct\":false},{\"text\":\"Yuqori (barqaror-sanogen), O\\u02bbrta (o\\u02bbtuvchi), Quyi (patogenga moyil)\",\"is_correct\":true}]', '2026-07-24 16:30:48', '2026-07-24 16:30:48', 'multiple_choice', NULL, NULL),
(50, 12, 'Raqamli taʼlim muhitida oʻqituvchilar faoliyatini kasbiy-psixologik monitoring qilishning (muntazam kuzatib borishning) asosiy vazifasi nima?', '[{\"text\":\"O\\u02bbqituvchilarning sanogen tafakkuri o\\u02bbsish dinamikasini kuzatib borish va ruhiy charchashning oldini olish\",\"is_correct\":true},{\"text\":\"O\\u02bbqituvchilar ustidan ma\\u02bcmuriy nazoratni kuchaytirish\",\"is_correct\":false},{\"text\":\"Har kuni yangi texnik topshiriqlar berish\",\"is_correct\":false},{\"text\":\"Faqat salbiy ko\\u02bbrsatkichlarni aniqlash va jazolash\",\"is_correct\":false}]', '2026-07-24 16:31:40', '2026-07-24 16:31:40', 'multiple_choice', NULL, NULL),
(51, 12, 'Raqamli taʼlim muhitida biologiya oʻqituvchilarining sanogen tafakkurini tashxis qilishning (aniqlashning) maqsadi va bunda qoʻllaniladigan asosiy usullar haqida tushuntirish bering.', '[]', '2026-07-24 16:35:18', '2026-07-24 16:35:18', 'open_ended', 'Kalit tushunchalar: Tashxis qilish, oʻz-oʻzini kuzatish soʻrovnomasi, ssenariyli pedagogik vaziyatlar, fikrlash naqshlari, xolis tahlil.', NULL),
(52, 12, 'Sanogen tafakkurni baholashning 5 ta asosiy yoʻnalishi (subshkalasi) va ularning dars jarayonidagi ahamiyatini yoritib bering.', '[]', '2026-07-24 16:35:49', '2026-07-24 16:35:49', 'open_ended', 'Kalit tushunchalar: Refleksivlik, kognitiv moslashuvchanlik, emotsional regulyatsiya, konstruktiv faollik, axborot selektivligi.', NULL),
(53, 12, 'Tashxis natijalariga koʻra oʻqituvchilarning sanogen tafakkur darajalari (yuqori, oʻrta, quyi) qanday xatti-harakat koʻrsatkichlari bilan farqlanadi?', '[]', '2026-07-24 16:36:17', '2026-07-24 16:36:17', 'open_ended', 'Kalit tushunchalar: Yuqori (barqaror-sanogen), oʻrta (oʻtuvchi), quyi (patogenga moyil), ruhiy muvozanat, zaxira reja, surunkali xavotirlik.', NULL),
(54, 12, 'Oʻqituvchilar faoliyatida kasbiy-psixologik monitoringni (muntazam kuzatuvni) tashkil etish qanday amalga oshiriladi va u ruhiy charchashning oldini olishga qanday xizmat qiladi?', '[]', '2026-07-24 16:36:53', '2026-07-24 16:36:53', 'open_ended', 'Kalit tushunchalar: Tizimli monitoring, kuzatuv xaritasi, shaxsiy rivojlanish trayektoriyasi, ruhiy charchash profilaktikasi, korreksiya.', NULL),
(55, 12, 'Tashxis jarayonida oʻqituvchida patogen (zararli) fikrlash unsurlari aniqlanganda, ularni sanogen (sogʻlom) holatga oʻtkazish boʻyicha qanday korreksiya va rivojlantirish ishlari olib boriladi?', '[]', '2026-07-24 16:37:21', '2026-07-24 16:37:21', 'open_ended', 'Kalit tushunchalar: Korreksiya rejasi, qayta baholash amaliyoti, A-B-C modeli, xolis refleksiya, psixologik-metodik yordam.', NULL),
(56, 13, 'Sanogen tafakkurni rivojlantirishning tizimli-lohiyaviy modelining o‘qituvchida emotsional barqarorlikni ta’minlash, kognitiv elastiklikni oshirish va ruhiy charchashning oldini olish vazifasini belgilab beruvchi bloki qaysi?', '[{\"text\":\"Texnologik-amaliy blok\",\"is_correct\":false},{\"text\":\"Maqsadli blok\",\"is_correct\":true},{\"text\":\"Natijaviy-baho bloki\",\"is_correct\":false},{\"text\":\"Mazmunli blok\",\"is_correct\":false}]', '2026-07-24 16:44:26', '2026-07-24 16:44:26', 'multiple_choice', NULL, NULL),
(57, 13, 'Biologiya o‘qituvchisining shaxsiy (individual) rivojlanish trayektoriyasini loyihalashtirishning birinchi va eng asosiy bosqichi qaysi javobda ko‘rsatilgan?', '[{\"text\":\"Shaxsiy maqsad va vazifalarni belgilash\",\"is_correct\":false},{\"text\":\"O\\u2018z-o\\u2018zini monitoring qilib borish\",\"is_correct\":false},{\"text\":\"Dastlabki tashxis (kuchli va zaif jihatlarni aniqlash)\",\"is_correct\":true},{\"text\":\"Amaliy-metodik mashqlarni bajarish\",\"is_correct\":false}]', '2026-07-24 16:45:13', '2026-07-24 16:45:13', 'multiple_choice', NULL, NULL),
(58, 13, 'Biologiya darsida kutilmagan texnik va metodik muammolarni salbiy hodisa emas, balki yangi pedagogik mahoratni egallash imkoniyati deb idrok etish sanogen modelning qaysi mexanizmiga kiradi?', '[{\"text\":\"Metakognitiv boshqaruv mexanizmi\",\"is_correct\":false},{\"text\":\"Kognitiv qayta qurish mexanizmi\",\"is_correct\":true},{\"text\":\"Konstruktiv moslashuvchanlik mexanizmi\",\"is_correct\":false},{\"text\":\"Tashqi rag\\u2018batlantirish mexanizmi\",\"is_correct\":false}]', '2026-07-24 16:46:07', '2026-07-24 16:46:07', 'multiple_choice', NULL, NULL),
(59, 13, 'Texnik nosozlik yuz berganda vahimaga tushmay, darhol oldindan tayyorlab qo‘yilgan zaxira dars ssenariysiga (doskada ishlash, tarqatma materiallar, muammoli savol-javob) o‘tishda qaysi mexanizm namoyon bo‘ladi?', '[{\"text\":\"Konstruktiv moslashuvchanlik mexanizmi\",\"is_correct\":true},{\"text\":\"Surunkali o\\u2018yga tolish mexanizmi\",\"is_correct\":false},{\"text\":\"Fojialashtirish va bo\\u2018rttirish mexanizmi\",\"is_correct\":false},{\"text\":\"Axborot ortiqchaligi mexanizmi\",\"is_correct\":false}]', '2026-07-24 16:47:14', '2026-07-24 16:47:14', 'multiple_choice', NULL, NULL),
(60, 13, 'Biologiya o‘qituvchilarida sanogen tafakkurni shakllantirishning tizimli-lohiyaviy modelini amaliyotga joriy etishning asosiy natijaviy ko‘rsatkichi qaysi javobda to‘g‘ri berilgan?', '[{\"text\":\"Dars soatlarini oshirish va faqat raqamli vositalardan foydalanish\",\"is_correct\":false},{\"text\":\"O\\u2018qituvchi ruhiy holatining barqarorlashuvi, ruhiy charchashning oldi olinishi va dars sifatining oshishi\",\"is_correct\":true},{\"text\":\"An\\u2019anaviy metodlarni to\\u2018liq taqiqlash\",\"is_correct\":false},{\"text\":\"Nazariy bilimlarni amaliyotsiz o\\u2018zlashtirish\",\"is_correct\":false}]', '2026-07-24 16:48:06', '2026-07-24 16:48:06', 'multiple_choice', NULL, NULL),
(61, 13, 'Biologiya o‘qituvchilarida sanogen tafakkurni shakllantirishning tizimli-lohiyaviy modelini tashkil etuvchi 4 ta asosiy blokni va ularning vazifalarini tushuntirib bering.', '[]', '2026-07-24 16:50:55', '2026-07-24 16:50:55', 'open_ended', 'Kalit tushunchalar: Maqsadli blok, mazmunli blok, texnologik-amaliy blok, natijaviy-baho bloki, tizimli yondashuv.', NULL),
(62, 13, 'Biologiya o‘qituvchisining shaxsiy (individual) rivojlanish trayektoriyasini loyihalashtirish qanday bosqichlardan iborat va u o‘qituvchining kasbiy o‘sishiga qanday ta’sir ko‘rsatadi?', '[]', '2026-07-24 16:51:27', '2026-07-24 16:51:27', 'open_ended', 'Kalit tushunchalar: Individual trayektoriya, dastlabki tashxis, shaxsiy maqsad, amaliy mashqlar, o‘z-o‘zini monitoring qilish, refleksiv kundalik.', NULL),
(63, 13, 'Sanogen modelni biologiya darslari amaliyotiga joriy etishda kognitiv qayta qurish va metakognitiv boshqaruv mexanizmlarining o‘rni nimadan iborat?', '[]', '2026-07-24 16:51:58', '2026-07-24 16:51:58', 'open_ended', 'Kalit tushunchalar: Kognitiv qayta qurish, metakognitiv boshqaruv, salbiy holatni imkoniyatga aylantirish, emotsional nazorat, axborot yuklamasi.', NULL),
(64, 13, 'Biologiya darsida kutilmagan texnik nosozlik yuz berganda \"Konstruktiv moslashuvchanlik mexanizmi\" amalda qanday namoyon bo‘ladi?', '[]', '2026-07-24 16:52:29', '2026-07-24 16:52:29', 'open_ended', 'Kalit tushunchalar: Konstruktiv moslashuvchanlik, zaxira dars ssenariysi, vahimaga tushmaslik, amaliy yechim, muammoli savol-javob.', NULL),
(65, 13, 'Tizimli-lohiyaviy model samaradorligini baholashda qanday asosiy natijaviy ko‘rsatkichlarga tayaniladi?', '[]', '2026-07-24 16:52:54', '2026-07-24 16:52:54', 'open_ended', 'Kalit tushunchalar: Ruhiy holat barqarorligi, kasbiy yonib bitish profilaktikasi, dars sifati, metodik moslashuvchanlik.', NULL),
(66, 14, 'Tajriba-sinov ishlarida sanogen tafakkurni shakllantirishning tizimli-lohiyaviy modeli, shaxsiy rivojlanish trayektoriyalari va zaxira dars rejalari bevosita qaysi bosqichda amaliyotga joriy etildi?', '[{\"text\":\"Aniqlovchi bosqich\",\"is_correct\":false},{\"text\":\"Shakllantiruvchi bosqich\",\"is_correct\":true},{\"text\":\"Nazorat-yakunlovchi bosqich\",\"is_correct\":false},{\"text\":\"Tayyorgarlik bosqichi\",\"is_correct\":false}]', '2026-07-24 17:17:26', '2026-07-24 17:17:26', 'multiple_choice', NULL, NULL),
(67, 14, 'Tajriba va nazorat guruhlarida erishilgan natijalarning statistik jihatdan ishonchliligini hamda tadqiqot gipotezasining to‘g‘riligini isbotlashda qaysi matematik-statistik usuldan foydalanildi?', '[{\"text\":\"Pirsonning xiy-kvadrat  va Styudentning t-meyori\",\"is_correct\":true},{\"text\":\"Faqat arifmetik o\\u2018rtacha qiymat\",\"is_correct\":false},{\"text\":\"Sotsiometrik so\\u2018rovnoma metodi\",\"is_correct\":false},{\"text\":\"Ekspert baholash va reyting usuli\",\"is_correct\":false}]', '2026-07-24 17:18:38', '2026-07-24 17:18:38', 'multiple_choice', NULL, NULL),
(68, 14, 'Tajriba guruhida o‘tkazilgan mashg‘ulotlardan so‘ng sanogen tafakkurning qaysi subshkalasi (yo‘nalishi) bo‘yicha eng yuqori o‘sish dinamikasi (+44.4%) kuzatildi?', '[{\"text\":\"Axborot selektivligi\",\"is_correct\":false},{\"text\":\"Refleksivlik\",\"is_correct\":false},{\"text\":\"Konstruktiv faollik\",\"is_correct\":true},{\"text\":\"Emotsional regulyatsiya\",\"is_correct\":false}]', '2026-07-24 17:19:28', '2026-07-24 17:19:28', 'multiple_choice', NULL, NULL),
(69, 14, 'Matematik-statistik tahlil jarayonida erishilgan moxiyatlilik darajasi p < 0.05 ko‘rsatkichi nimani anglatadi?', '[{\"text\":\"Tajriba guruhida erishilgan ijobiy natijalar statistik jihatdan ishonchli va tasodifiy emaslig\",\"is_correct\":true},{\"text\":\"Tajriba-sinov ishlari yetarsiz o\\u2018tkazilganligini\",\"is_correct\":false},{\"text\":\"Nazorat va tajriba guruhlari o\\u2018rtasida hech qanday farq yo\\u2018qligini\",\"is_correct\":false},{\"text\":\"Natijalarni amaliyotda qo\\u2018llab bo\\u2018lmasligini\",\"is_correct\":false}]', '2026-07-24 17:20:40', '2026-07-24 17:20:40', 'multiple_choice', NULL, NULL),
(70, 14, 'Tajriba-sinov ishlari xulosalariga tayanib, biologiya o‘qituvchilari uchun berilgan ilmiy-metodik tavsiyalarning asosiy mazmuni nimadan iborat?', '[{\"text\":\"Raqamli texnologiyalardan foydalanishni to\\u2018xtatish\",\"is_correct\":false},{\"text\":\"Malaka oshirish dasturlariga \\\"Sanogen tafakkur\\\" modulini kiritish hamda muqobil (Plan B) dars ssenariylarini yaratish\",\"is_correct\":true},{\"text\":\"Faqat nazariy bilimlarni oshirish bilan cheklanish\",\"is_correct\":false},{\"text\":\"Dars soatlarini qisqartirish\",\"is_correct\":false}]', '2026-07-24 17:21:38', '2026-07-24 17:21:38', 'multiple_choice', NULL, NULL),
(71, 14, 'Tajriba-sinov ishlarini tashkil etishning 3 ta asosiy bosqichi (aniqlovchi, shakllantiruvchi, nazorat-yakunlovchi) va ularning pedagogik vazifalarini tushuntirib bering.', '[]', '2026-07-24 17:22:41', '2026-07-24 17:22:41', 'open_ended', 'Kalit tushunchalar: Aniqlovchi bosqich, shakllantiruvchi bosqich, nazorat-yakunlovchi bosqich, dastlabki tashxis, sanogen model, zaxira dars ssenariylari, qayta baholash.', NULL),
(72, 14, 'Tajriba-sinov natijalarining ishonchliligini baholashda qanday matematik-statistik usullardan foydalanildi va erishilgan moxiyatlilik darajasining (p < 0.05) ilmiy-amaliy ahamiyati nimada?', '[]', '2026-07-24 17:23:52', '2026-07-24 17:23:52', 'open_ended', 'Kalit tushunchalar: Pirsonning xiy-kvadrat meyori, Styudentning t-meyori, moxiyatlilik darajasi (p < 0.05), matematik-statistik tahlil, gipotezani tasdiqlash, ishonchlilik.', NULL),
(73, 14, 'Sanogen tafakkurning 5 ta subshkalasi bo‘yicha tajriba guruhida erishilgan o‘sish dinamikasini tahlil qiling. Qaysi yo‘nalishda eng yuqori ko‘rsatkich kuzatildi?', '[]', '2026-07-24 17:24:22', '2026-07-24 17:24:22', 'open_ended', 'Kalit tushunchalar: Refleksivlik (+35.7%), kognitiv moslashuvchanlik (+43.5%), emotsional regulyatsiya (+37.9%), konstruktiv faollik (+44.4%), axborot selektivligi (+30.8%), o‘sish dinamikasi.', NULL),
(74, 14, 'Sanogen tafakkur modelining joriy etilishi biologiya o‘qituvchilarining kasbiy faoliyatida va o‘quvchilar o‘zlashtirishida qanday sifat o‘zgarishlarini ta’minladi?', '[]', '2026-07-24 17:24:52', '2026-07-24 17:24:52', 'open_ended', 'Kalit tushunchalar: Emotsional zo‘riqishning pasayishi, ruhiy charchash profilaktikasi, metodik xotirjamlik, ta’lim sifati, o‘quvchilar o‘zlashtirishining oshishi.', NULL),
(75, 14, 'Tajriba-sinov ishlari xulosalaridan kelib chiqib, biologiya o‘qituvchilarining malakasini oshirish va ta’lim amaliyoti uchun qanday ilmiy-metodik tavsiyalar berildi?', '[]', '2026-07-24 17:25:15', '2026-07-24 17:25:15', 'open_ended', 'Kalit tushunchalar: Malaka oshirish dasturlari, zaxira (Plan B) dars ssenariylari, standartlashtirish, shaxsiy rivojlanish trayektoriyasi, refleksiv kundalik.', NULL),
(76, 15, '\"SanoTafEdu\" raqamli platformasidagi \"Shaxsiy boshqaruv paneli\" ning asosiy vazifasi nimadan iborat?', '[{\"text\":\"O\\u2018qituvchining sanogen tafakkur subshkalari bo\\u2018yicha o\\u2018sish ko\\u2018rsatkichlarini real vaqt rejimida vizual grafiklarda aks ettirish\",\"is_correct\":true},{\"text\":\"O\\u2018qituvchining ish haqi va ish soatlarini hisoblash\",\"is_correct\":false},{\"text\":\"Dars jadvallarini tuzish\",\"is_correct\":false},{\"text\":\"O\\u2018quvchilarning davomatini tekshirish\",\"is_correct\":false}]', '2026-07-24 17:32:42', '2026-07-24 17:32:42', 'multiple_choice', NULL, NULL),
(77, 15, '\"SanoTafEdu\" platformasiga integratsiyalangan sun’iy intellekt moduli darsdagi muammoli holatlarda o‘qituvchiga qanday yordam beradi?', '[{\"text\":\"Darsni o\\u2018qituvchi o\\u2018rniga o\\u2018tib beradi\",\"is_correct\":false},{\"text\":\"A-B-C kognitiv modeli asosida salbiy fikrni rivojlantiruvchi va sog\\u2018lom (sanogen) ramkaga ko\\u2018chirish bo\\u2018yicha shaxsiy tavsiyalar beradi\",\"is_correct\":true},{\"text\":\"Texnik nosozliklarni avtomatik ravishda tuzatadi\",\"is_correct\":false},{\"text\":\"O\\u2018qituvchiga ma\\u2019muriy chora ko\\u2018rishni taklif qiladi\",\"is_correct\":false}]', '2026-07-24 17:33:33', '2026-07-24 17:33:33', 'multiple_choice', NULL, NULL),
(78, 15, '\"SanoTafEdu\" platformasida o‘yinlashtirish (gamifikatsiya) texnologiyasidan foydalanishning asosiy maqsadi nima?', '[{\"text\":\"Faqat ko\\u2018ngilochar o\\u2018yinlar tashkil etish\",\"is_correct\":false},{\"text\":\"O\\u2018qituvchining zaxira dars rejalarini tuzishi, refleksiv kundalik yuritishi va o\\u2018z-o\\u2018zini rivojlantirish motivatsiyasini barqarorlashtirish\",\"is_correct\":true},{\"text\":\"O\\u2018qituvchilar o\\u2018rtasida musobaqa tashkil qilib ularni jazolash\",\"is_correct\":false},{\"text\":\"An\\u2019anaviy ta\\u2019lim metodlarini to\\u2018liq bekor qilish\",\"is_correct\":false}]', '2026-07-24 17:34:29', '2026-07-24 17:34:29', 'multiple_choice', NULL, NULL),
(79, 15, 'Biologiya o‘qituvchisining \"SanoTafEdu\" platformasi orqali uzluksiz o‘z-o‘zini takomillashtirish modelining ikkinchi (modellashtirish va zaxiralash) bosqichida nima amalga oshiriladi?', '[{\"text\":\"Dastlabki kognitiv zaifliklar aniqlanadi\",\"is_correct\":false},{\"text\":\"Raqamli biologiya darslari uchun muqobil (Plan B) zaxira ssenariylari boyitib boriladi\",\"is_correct\":true},{\"text\":\"Natijalar faqat qog\\u2018ozga ko\\u2018chiriladi\",\"is_correct\":false},{\"text\":\"Platformadan foydalanish to\\u2018xtatiladi\",\"is_correct\":false}]', '2026-07-24 17:35:19', '2026-07-24 17:35:19', 'multiple_choice', NULL, NULL),
(80, 15, '\"SanoTafEdu\" platformasi orqali biologiya o‘qituvchisida sanogen tafakkurning rivojlanishi o‘quvchilar ta’lim faoliyatiga qanday ta’sir ko‘rsatadi?', '[{\"text\":\"O\\u2018quvchilarda darsdagi xavotirlik va qo\\u2018rquv pasayadi, xatolarga tajriba sifatida qaraydigan sanogen ta\\u2019lim muhiti shakllanadi\",\"is_correct\":true},{\"text\":\"O\\u2018quvchilarning biologiyaga bo\\u2018lgan qiziqishi pasayadi\",\"is_correct\":false},{\"text\":\"Darsda intizom buziladi\",\"is_correct\":false},{\"text\":\"Faqat nazariy bilimlarni yodlash kuchayadi\",\"is_correct\":false}]', '2026-07-24 17:36:10', '2026-07-24 17:36:10', 'multiple_choice', NULL, NULL),
(81, 16, 'Interaktiv mahorat darslarining an’anaviy ma’ruzalardan farqli ravishda biologiya o‘qituvchilarida sanogen tafakkurni rivojlantirishdagi afzalliklarini tushuntirib bering.', '[]', '2026-07-24 17:42:47', '2026-07-24 17:42:47', 'open_ended', 'Kalit tushunchalar: Interaktiv mahorat darslari, muammoli ssenariylar, jonli tajriba, zaxira dars rejasi, sanogen refleksiya, amaliy ko‘nikma.', NULL),
(82, 16, 'Kasbiy hamjamiyatlarda (metodik birlashmalarda) sanogen muloqot muhitini qaror toptirishning 4 ta asosiy ustunini va ularning ahamiyatini bayon qiling.', '[]', '2026-07-24 17:43:13', '2026-07-24 17:43:13', 'open_ended', 'Kalit tushunchalar: O‘zaro ishonch, tengdosh ustozligi, zaxira banki, doimiy muloqot, kasbiy hamjamiyat, tanqidsiz tahlil.', NULL),
(83, 16, 'Darsni birgalikda tahlil qilish (Lesson Study) jarayonida o‘qituvchining kasbiy yonib bitishi hamda xavotirligining oldini olish uchun qanday pedagogik qoidalarga rioya qilinadi?', '[]', '2026-07-24 17:43:43', '2026-07-24 17:43:43', 'open_ended', 'Kalit tushunchalar: Birgalikda rejalashtirish, shaxsiyatni emas metodni tahlil qilish, qo‘llab-quvvatlovchi muloqot, sanogen tahlil kartasi.', NULL),
(84, 16, 'An’anaviy metodik birlashma yig‘ilishlari bilan sanogen kasbiy hamjamiyat muloqoti o‘rtasidagi asosiy farqlarni qanday mezonlar bo‘yicha ajratish mumkin?', '[]', '2026-07-24 17:44:12', '2026-07-24 17:44:12', 'open_ended', 'Kalit tushunchalar: Muloqot uslubi, xatolarga munosabat, o‘qituvchi ruhiyati, rasmiylatchilik, konstruktiv yechim', NULL),
(85, 16, 'Maktab va tuman miqyosida \"Zaxira dars ishlanmalari banki\"ni shakllantirish biologiya o‘qituvchisining darsdagi emotsional barqarorligiga qanday ta’sir ko‘rsatadi?', '[]', '2026-07-24 17:44:48', '2026-07-24 17:44:48', 'open_ended', 'Kalit tushunchalar: Zaxira dars ishlanmalari banki, muqobil reja (Plan B), emotsional barqarorlik, kognitiv tayyorgarlik, xavotirlikni pasaytirish.', NULL);
